-- ===== work-message-files-local.sql =====
-- LOCAL PRO ONLY. Round 8 (2026-11-15): attachments in the job messages (Round 7C) between the
-- professional and the linked customer. Photos (JPG; PNG/WebP are converted to JPG by the server)
-- and PDF up to 20 MiB, in the private bucket `pro-work-message-files` (never public; every
-- download is reauthorized here and served by the API). Same visibility rule as the messages: only
-- the two sides of the thread (pro_work_message_side). The message and its file are written in one
-- transaction, idempotent by actionId (= message id = file id); both are immutable.
begin;
create table if not exists public.pro_work_message_files(
 owner_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,message_id uuid not null,request_id uuid not null,side text not null check(side in('pro','client')),
 name text not null check(length(name) between 1 and 160 and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 mime_type text not null check(mime_type in('image/jpeg','application/pdf')),
 size_bytes integer not null check(size_bytes between 1 and 20971520),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 object_path text not null unique,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),
 foreign key(owner_id,message_id) references public.pro_work_messages(owner_id,id),
 check(right(name,4)=case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(object_path=owner_id::text||'/'||request_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end));
create index if not exists pro_work_message_files_request on public.pro_work_message_files(request_id,created_at);

create or replace function public.pro_work_message_file_json(f public.pro_work_message_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',f.id,'messageId',f.message_id,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'createdAt',f.created_at)
$$;
-- Object path the server must upload to before calling pro_work_message_attach (side checked).
create or replace function public.pro_work_message_file_path(p_actor uuid,p_request uuid,p_file uuid,p_mime text) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;
begin
 if public.pro_work_message_side(p_actor,p_request) is null then raise exception 'Forbidden' using errcode='42501';end if;
 if p_mime not in('image/jpeg','application/pdf') or p_file is null then raise exception 'Invalid file' using errcode='22023';end if;
 select * into r from public.pro_appointment_requests where id=p_request;
 return r.owner_id::text||'/'||p_request::text||'/'||p_file::text||case when p_mime='application/pdf' then '.pdf' else '.jpg' end;
end $$;
create or replace function public.pro_work_message_attach(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];rid uuid;aid uuid;me text;r public.pro_appointment_requests;f public.pro_work_message_files;posted jsonb;bytes integer;mime text;nm text;body_text text;
begin
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['actionId','body','mimeType','name','requestId','sha256','sizeBytes'] then raise exception 'Invalid attachment' using errcode='22023';end if;
 begin rid:=(p_input->>'requestId')::uuid;aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid attachment' using errcode='22023';end;
 me:=public.pro_work_message_side(p_actor,rid);if me is null then raise exception 'Forbidden' using errcode='42501';end if;
 mime:=p_input->>'mimeType';nm:=p_input->>'name';
 if mime not in('image/jpeg','application/pdf') or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false)
  or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'body') is distinct from 'string' then raise exception 'Invalid attachment' using errcode='22023';end if;
 bytes:=(p_input->>'sizeBytes')::integer;if bytes<1 or bytes>20971520 then raise exception 'File too large' using errcode='22023';end if;
 select * into r from public.pro_appointment_requests where id=rid;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-message:'||p_actor::text||':'||aid::text,0));
 select * into f from public.pro_work_message_files where owner_id=r.owner_id and id=aid;
 if found then
  if f.sha256<>p_input->>'sha256' or f.request_id<>rid or f.name<>nm then raise exception 'Action id reused' using errcode='22023';end if;
  return jsonb_build_object('message',(select public.pro_work_message_json(m) from public.pro_work_messages m where m.owner_id=r.owner_id and m.id=aid),'file',public.pro_work_message_file_json(f),'replayed',true);
 end if;
 body_text:=coalesce(nullif(btrim(p_input->>'body'),''),nm);
 -- The message goes through the existing writer (side, rate limit, read marker, receipt).
 posted:=public.pro_work_messages_mutate(p_actor,jsonb_build_object('action','post','actionId',aid,'body',body_text,'requestId',rid));
 insert into public.pro_work_message_files(owner_id,id,message_id,request_id,side,name,mime_type,size_bytes,sha256,object_path)
  values(r.owner_id,aid,aid,rid,me,nm,mime,bytes,p_input->>'sha256',public.pro_work_message_file_path(p_actor,rid,aid,mime)) returning * into f;
 return jsonb_build_object('message',posted->'message','file',public.pro_work_message_file_json(f));
end $$;
create or replace function public.pro_work_message_files_read(p_actor uuid,p_request uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if public.pro_work_message_side(p_actor,p_request) is null then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('requestId',p_request,'files',coalesce((select jsonb_agg(public.pro_work_message_file_json(f) order by f.created_at,f.id) from public.pro_work_message_files f where f.request_id=p_request),'[]'::jsonb));
end $$;
create or replace function public.pro_work_message_file_download(p_actor uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f public.pro_work_message_files;
begin
 select * into f from public.pro_work_message_files where id=p_file;
 if not found or public.pro_work_message_side(p_actor,f.request_id) is null then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;
create or replace function public.pro_work_message_files_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Message attachments are immutable' using errcode='23514';end $$;
do $$declare f record;begin
 alter table public.pro_work_message_files enable row level security;
 revoke all on public.pro_work_message_files from public,anon,authenticated;grant select,insert,update,delete on public.pro_work_message_files to service_role;
 drop trigger if exists pro_work_message_files_immutable on public.pro_work_message_files;
 create trigger pro_work_message_files_immutable before update or delete on public.pro_work_message_files for each row when (pg_trigger_depth()=0) execute function public.pro_work_message_files_immutable();
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_work_message_file_json','pro_work_message_file_path','pro_work_message_attach','pro_work_message_files_read','pro_work_message_file_download','pro_work_message_files_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-work-message-files','pro-work-message-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
  if not exists(select 1 from storage.buckets where id='pro-work-message-files' and not public and file_size_limit=20971520) then raise exception 'Message files bucket configuration';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== work-file-organizer-local.sql =====
-- LOCAL PRO ONLY. Round 8 (2026-11-15): organizer for the files of a job (Archivos del trabajo).
-- Folders and subfolders (depth ≤ 5), move, rename (display name, same extension), favorites,
-- trash with restore and search. The uploaded file rows (pro_work_files) and their bytes are never
-- changed or deleted: the organizer keeps its own metadata (pro_work_file_meta) and folders.
-- Trash: a trashed file or folder (with everything inside) leaves the normal views and can be
-- restored; the trash shows «se puede restaurar hasta» = trashed_at + 30 days (retention note).
-- Nothing is purged automatically in this local suite (data is never lost; a purge job would need
-- authorization). Sharing with the customer and versions keep their own rules: what was already
-- shared stays shared (immutable publication); a trashed file cannot be shared again from the UI.
-- Patterns: RLS on, service_role-only, CAS 40001, idempotent actionId, immutable history.
begin;
create table if not exists public.pro_work_file_folders(
 owner_id uuid not null,id uuid not null,work_id text not null,parent_id uuid,
 name text not null check(length(btrim(name)) between 1 and 80 and name=btrim(name) and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 trashed_at timestamptz,revision integer not null default 1 check(revision>0),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,parent_id) references public.pro_work_file_folders(owner_id,id),
 check(parent_id is distinct from id));
create index if not exists pro_work_file_folders_parent on public.pro_work_file_folders(owner_id,work_id,parent_id);
create table if not exists public.pro_work_file_meta(
 owner_id uuid not null,file_id uuid not null,work_id text not null,folder_id uuid,
 display_name text check(display_name is null or (length(display_name) between 1 and 160 and display_name !~ '[[:cntrl:]/]' and position(chr(92) in display_name)=0)),
 favorite boolean not null default false,trashed_at timestamptz,revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,file_id),
 foreign key(owner_id,work_id,file_id) references public.pro_work_files(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,folder_id) references public.pro_work_file_folders(owner_id,id));
create table if not exists public.pro_work_file_organizer_history(
 owner_id uuid not null,action_id uuid not null,action text not null,subject text not null check(subject in('file','folder')),subject_id uuid not null,
 before_row jsonb,after_row jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_work_file_organizer_actions(
 owner_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));

-- True when the folder or one of its ancestors is in the trash.
create or replace function public.pro_wfo_folder_trashed(p_owner uuid,p_folder uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 with recursive up as(select id,parent_id,trashed_at,1 depth from public.pro_work_file_folders where owner_id=p_owner and id=p_folder
  union all select f.id,f.parent_id,f.trashed_at,up.depth+1 from public.pro_work_file_folders f join up on f.owner_id=p_owner and f.id=up.parent_id where up.depth<8)
 select coalesce(bool_or(trashed_at is not null),false) from up
$$;
create or replace function public.pro_wfo_folder_depth(p_owner uuid,p_folder uuid) returns integer language sql stable security invoker set search_path=public,pg_temp as $$
 with recursive up as(select id,parent_id,1 depth from public.pro_work_file_folders where owner_id=p_owner and id=p_folder
  union all select f.id,f.parent_id,up.depth+1 from public.pro_work_file_folders f join up on f.owner_id=p_owner and f.id=up.parent_id where up.depth<8)
 select coalesce(max(depth),0) from up
$$;
create or replace function public.pro_wfo_subtree_height(p_owner uuid,p_folder uuid) returns integer language sql stable security invoker set search_path=public,pg_temp as $$
 with recursive down as(select id,1 h from public.pro_work_file_folders where owner_id=p_owner and id=p_folder
  union all select f.id,down.h+1 from public.pro_work_file_folders f join down on f.owner_id=p_owner and f.parent_id=down.id where down.h<8)
 select coalesce(max(h),0) from down
$$;
create or replace function public.pro_wfo_folder_json(f public.pro_work_file_folders) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',f.id,'parentId',f.parent_id,'name',f.name,'revision',f.revision,'trashedAt',f.trashed_at,
  'restoreUntil',case when f.trashed_at is not null then ((f.trashed_at at time zone 'America/Costa_Rica')::date+30)::text end,
  'items',(select count(*) from public.pro_work_file_meta m where m.owner_id=f.owner_id and m.folder_id=f.id and m.trashed_at is null)+(select count(*) from public.pro_work_file_folders c where c.owner_id=f.owner_id and c.parent_id=f.id and c.trashed_at is null))
$$;
create or replace function public.pro_wfo_file_json(p_file public.pro_work_files,m public.pro_work_file_meta) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_work_file_json(p_file)||jsonb_build_object('originalName',p_file.name,'name',coalesce(m.display_name,p_file.name),'folderId',m.folder_id,'favorite',coalesce(m.favorite,false),
  'trashedAt',m.trashed_at,'restoreUntil',case when m.trashed_at is not null then ((m.trashed_at at time zone 'America/Costa_Rica')::date+30)::text end,'metaRevision',coalesce(m.revision,0))
$$;

create or replace function public.pro_work_file_organizer_read(p_actor uuid,p_work text,p_view text,p_folder uuid default null,p_q text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare q text:=lower(btrim(coalesce(p_q,'')));crumbs jsonb;folders jsonb;files jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_view not in('folder','favorites','trash','search') or length(q)>80 then raise exception 'Invalid file query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 if p_folder is not null and not exists(select 1 from public.pro_work_file_folders where owner_id=p_actor and work_id=p_work and id=p_folder) then return null;end if;
 if p_view='folder' then
  if p_folder is not null and public.pro_wfo_folder_trashed(p_actor,p_folder) then return null;end if;
  with recursive up as(select id,parent_id,name,1 depth from public.pro_work_file_folders where owner_id=p_actor and id=p_folder
   union all select f.id,f.parent_id,f.name,up.depth+1 from public.pro_work_file_folders f join up on f.owner_id=p_actor and f.id=up.parent_id where up.depth<8)
  select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name) order by depth desc),'[]'::jsonb) into crumbs from up;
  select coalesce(jsonb_agg(public.pro_wfo_folder_json(f) order by lower(f.name),f.id),'[]'::jsonb) into folders from public.pro_work_file_folders f where f.owner_id=p_actor and f.work_id=p_work and f.parent_id is not distinct from p_folder and f.trashed_at is null;
  select coalesce(jsonb_agg(public.pro_wfo_file_json(w,m) order by w.created_at desc,w.id),'[]'::jsonb) into files from public.pro_work_files w left join public.pro_work_file_meta m on m.owner_id=w.owner_id and m.file_id=w.id
   where w.owner_id=p_actor and w.work_id=p_work and w.ready and m.trashed_at is null and m.folder_id is not distinct from p_folder;
 elsif p_view='trash' then
  crumbs:='[]'::jsonb;
  -- Top-level trashed items only (contents of a trashed folder come back with it).
  select coalesce(jsonb_agg(public.pro_wfo_folder_json(f) order by f.trashed_at desc,f.id),'[]'::jsonb) into folders from public.pro_work_file_folders f where f.owner_id=p_actor and f.work_id=p_work and f.trashed_at is not null and (f.parent_id is null or not public.pro_wfo_folder_trashed(p_actor,f.parent_id));
  select coalesce(jsonb_agg(public.pro_wfo_file_json(w,m) order by m.trashed_at desc,w.id),'[]'::jsonb) into files from public.pro_work_files w join public.pro_work_file_meta m on m.owner_id=w.owner_id and m.file_id=w.id
   where w.owner_id=p_actor and w.work_id=p_work and w.ready and m.trashed_at is not null and (m.folder_id is null or not public.pro_wfo_folder_trashed(p_actor,m.folder_id));
 else
  crumbs:='[]'::jsonb;folders:='[]'::jsonb;
  select coalesce(jsonb_agg(public.pro_wfo_file_json(w,m) order by w.created_at desc,w.id),'[]'::jsonb) into files from public.pro_work_files w left join public.pro_work_file_meta m on m.owner_id=w.owner_id and m.file_id=w.id
   where w.owner_id=p_actor and w.work_id=p_work and w.ready and m.trashed_at is null and (m.folder_id is null or not public.pro_wfo_folder_trashed(p_actor,m.folder_id))
    and (p_view<>'favorites' or coalesce(m.favorite,false)) and (q='' or strpos(lower(coalesce(m.display_name,w.name)),q)>0 or strpos(lower(w.name),q)>0);
  if p_view='search' and q<>'' then
   select coalesce(jsonb_agg(public.pro_wfo_folder_json(f) order by lower(f.name),f.id),'[]'::jsonb) into folders from public.pro_work_file_folders f where f.owner_id=p_actor and f.work_id=p_work and f.trashed_at is null and not public.pro_wfo_folder_trashed(p_actor,f.id) and strpos(lower(f.name),q)>0;
  end if;
 end if;
 return jsonb_build_object('workId',p_work,'view',p_view,'folderId',p_folder,'breadcrumb',crumbs,'folders',folders,'files',files,
  'allFolders',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'parentId',f.parent_id,'name',f.name) order by lower(f.name),f.id) from public.pro_work_file_folders f where f.owner_id=p_actor and f.work_id=p_work and f.trashed_at is null and not public.pro_wfo_folder_trashed(p_actor,f.id)),'[]'::jsonb),
  'trashCount',(select count(*) from public.pro_work_file_meta m where m.owner_id=p_actor and m.work_id=p_work and m.trashed_at is not null)+(select count(*) from public.pro_work_file_folders f where f.owner_id=p_actor and f.work_id=p_work and f.trashed_at is not null));
end $$;

create or replace function public.pro_work_file_organizer_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text:=p_input->>'action';aid uuid;wid text:=p_input->>'workId';keys text[];hash text:=md5(p_input::text);prior public.pro_work_file_organizer_actions;
 fo public.pro_work_file_folders;m public.pro_work_file_meta;w public.pro_work_files;target uuid;sid uuid;rev integer;nm text;before_json jsonb;after_json jsonb;answer jsonb;subj text;had_meta boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file action' using errcode='22023';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if act is null or not(
   act='create_folder' and keys=array['action','actionId','folderId','name','parentId','workId']
   or act in('rename_folder','rename_file') and keys=array['action','actionId','name','revision','subjectId','workId']
   or act in('move_folder','move_file') and keys=array['action','actionId','revision','subjectId','targetId','workId']
   or act in('trash_folder','restore_folder','trash_file','restore_file') and keys=array['action','actionId','revision','subjectId','workId']
   or act='favorite_file' and keys=array['action','actionId','on','revision','subjectId','workId']) then raise exception 'Invalid file action' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;sid:=nullif(p_input->>'subjectId','')::uuid;target:=nullif(coalesce(p_input->>'targetId',p_input->>'parentId'),'')::uuid;
  if p_input ? 'revision' then rev:=(p_input->>'revision')::integer;end if;exception when others then raise exception 'Invalid file action' using errcode='22023';end;
 if wid is null or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-wfo:'||p_actor::text||':'||wid,0));
 select * into prior from public.pro_work_file_organizer_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if target is not null and (not exists(select 1 from public.pro_work_file_folders where owner_id=p_actor and work_id=wid and id=target) or public.pro_wfo_folder_trashed(p_actor,target)) then raise exception 'Folder unavailable' using errcode='40001';end if;
 if act in('create_folder','rename_folder','rename_file') then
  if jsonb_typeof(p_input->'name') is distinct from 'string' then raise exception 'Invalid name' using errcode='22023';end if;nm:=btrim(p_input->>'name');
 end if;
 if act like '%_folder' then
  subj:='folder';
  if act='create_folder' then
   begin sid:=(p_input->>'folderId')::uuid;exception when others then raise exception 'Invalid file action' using errcode='22023';end;
   if length(nm) not between 1 and 80 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 then raise exception 'Invalid name' using errcode='22023';end if;
   if target is not null and public.pro_wfo_folder_depth(p_actor,target)>=5 then raise exception 'Folder too deep' using errcode='22023';end if;
   if (select count(*) from public.pro_work_file_folders where owner_id=p_actor and work_id=wid)>=200 then raise exception 'Folder limit' using errcode='54000';end if;
   insert into public.pro_work_file_folders(owner_id,id,work_id,parent_id,name) values(p_actor,sid,wid,target,nm) returning * into fo;
  else
   select * into fo from public.pro_work_file_folders where owner_id=p_actor and work_id=wid and id=sid for update;
   if not found then raise exception 'Forbidden' using errcode='42501';end if;
   if fo.revision<>rev then raise exception 'Folder changed' using errcode='40001';end if;
   before_json:=public.pro_wfo_folder_json(fo);
   if act='rename_folder' then
    if length(nm) not between 1 and 80 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 then raise exception 'Invalid name' using errcode='22023';end if;
    update public.pro_work_file_folders set name=nm,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='move_folder' then
    if fo.trashed_at is not null then raise exception 'Restore before moving' using errcode='22023';end if;
    -- No cycles: the target cannot be the folder itself or one of its descendants.
    if target is not null and exists(with recursive down as(select id,1 h from public.pro_work_file_folders where owner_id=p_actor and id=sid union all select f.id,down.h+1 from public.pro_work_file_folders f join down on f.owner_id=p_actor and f.parent_id=down.id where down.h<8) select 1 from down where id=target) then raise exception 'Invalid move' using errcode='22023';end if;
    if coalesce(public.pro_wfo_folder_depth(p_actor,target),0)+public.pro_wfo_subtree_height(p_actor,sid)>5 then raise exception 'Folder too deep' using errcode='22023';end if;
    update public.pro_work_file_folders set parent_id=target,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   elsif act='trash_folder' then
    if fo.trashed_at is not null then raise exception 'Already in trash' using errcode='40001';end if;
    update public.pro_work_file_folders set trashed_at=clock_timestamp(),revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   else
    if fo.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
    -- Restored into the root when its parent is still in the trash.
    update public.pro_work_file_folders set trashed_at=null,parent_id=case when parent_id is not null and public.pro_wfo_folder_trashed(p_actor,parent_id) then null else parent_id end,revision=revision+1 where owner_id=p_actor and id=sid returning * into fo;
   end if;
  end if;
  after_json:=public.pro_wfo_folder_json(fo);answer:=jsonb_build_object('action',act,'folder',after_json);
 else
  subj:='file';
  select * into w from public.pro_work_files where owner_id=p_actor and work_id=wid and id=sid and ready;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  select * into m from public.pro_work_file_meta where owner_id=p_actor and file_id=sid for update;
  had_meta:=found;
  if coalesce(m.revision,0)<>rev then raise exception 'File changed' using errcode='40001';end if;
  before_json:=public.pro_wfo_file_json(w,m);
  if not had_meta then insert into public.pro_work_file_meta(owner_id,file_id,work_id) values(p_actor,sid,wid) returning * into m;else update public.pro_work_file_meta set revision=revision+1,updated_at=clock_timestamp() where owner_id=p_actor and file_id=sid returning * into m;end if;
  if act='rename_file' then
   if length(nm) not between 5 and 160 or nm ~ '[[:cntrl:]/]' or position(chr(92) in nm)>0 or lower(right(nm,4))<>right(w.name,4) then raise exception 'Invalid name' using errcode='22023';end if;
   nm:=left(nm,length(nm)-4)||right(w.name,4);
   update public.pro_work_file_meta set display_name=case when nm=w.name then null else nm end where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='move_file' then
   if m.trashed_at is not null then raise exception 'Restore before moving' using errcode='22023';end if;
   update public.pro_work_file_meta set folder_id=target where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='favorite_file' then
   if jsonb_typeof(p_input->'on') is distinct from 'boolean' then raise exception 'Invalid file action' using errcode='22023';end if;
   update public.pro_work_file_meta set favorite=(p_input->>'on')::boolean where owner_id=p_actor and file_id=sid returning * into m;
  elsif act='trash_file' then
   if m.trashed_at is not null then raise exception 'Already in trash' using errcode='40001';end if;
   update public.pro_work_file_meta set trashed_at=clock_timestamp() where owner_id=p_actor and file_id=sid returning * into m;
  else
   if m.trashed_at is null then raise exception 'Not in trash' using errcode='40001';end if;
   update public.pro_work_file_meta set trashed_at=null,folder_id=case when folder_id is not null and public.pro_wfo_folder_trashed(p_actor,folder_id) then null else folder_id end where owner_id=p_actor and file_id=sid returning * into m;
  end if;
  after_json:=public.pro_wfo_file_json(w,m);answer:=jsonb_build_object('action',act,'file',after_json);
 end if;
 insert into public.pro_work_file_organizer_history(owner_id,action_id,action,subject,subject_id,before_row,after_row) values(p_actor,aid,act,subj,sid,before_json,after_json);
 insert into public.pro_work_file_organizer_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;

create or replace function public.pro_wfo_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'File organizer history is immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_work_file_folders','pro_work_file_meta','pro_work_file_organizer_history','pro_work_file_organizer_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_work_file_organizer_history','pro_work_file_organizer_actions'] loop
  execute format('drop trigger if exists pro_wfo_immutable on public.%I',t);execute format('create trigger pro_wfo_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_wfo_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_wfo_folder_trashed','pro_wfo_folder_depth','pro_wfo_subtree_height','pro_wfo_folder_json','pro_wfo_file_json','pro_work_file_organizer_read','pro_work_file_organizer_mutate','pro_wfo_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== time-report-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): global hours view across jobs (read only).
-- One ledger: stopped time entries (Horas, cronómetro por persona) with their LIVE job-cost line
-- (edits in Costos follow the chain; voided lines are excluded) plus time lines recorded directly in
-- «Costos y pagos» (source 'ledger'), exactly as the per-job Horas view counts them, so totals never
-- disagree. Filters: period (≤ 366 days, America/Costa_Rica dates), job, person, billable.
-- Person: the person timer's person, else the person recorded for the entry (pro_time_entry_people),
-- else the account owner. Nothing is written. RLS + service_role-only; security invoker.
begin;
create or replace function public.pro_time_report_rows(p_actor uuid,p_from date,p_to date) returns table(
 id uuid,work_id text,work_title text,recorded_on date,minutes integer,billable boolean,rate_cents bigint,billable_cents bigint,cost_cents bigint,
 activity_name text,person_key text,person_name text,source text,note text,created_at timestamptz)
language sql stable security invoker set search_path=public,pg_temp as $$
 with mine as(
  select e.*,l.minutes live_minutes,l.hourly_cost_cents line_cost,l.amount_cents line_amount,l.id live_id
  from public.pro_time_entries e join public.pro_work_cost_entries l on l.user_id=e.owner_id and l.id=public.pro_time_live_line(e.owner_id,e.cost_entry_id)
  where e.owner_id=p_actor and e.status='stopped' and e.recorded_on between p_from and p_to)
 select m.id,m.work_id,w.service,m.recorded_on,m.live_minutes,m.billable,m.rate_cents,
  case when m.billable and m.rate_cents is not null then round(m.live_minutes::numeric*m.rate_cents/60)::bigint end,
  case when m.line_cost is not null then m.line_amount end,
  a.name,
  coalesce('person:'||t.person_id::text,case when pp.grant_id is not null then 'grant:'||pp.grant_id::text end,case when pp.name is not null and pp.name<>'Propietario' then 'name:'||pp.name end,'owner'),
  coalesce(nullif(t.person_name,''),pp.name,'Propietario'),m.source,m.note,m.created_at
 from mine m join public.pro_work w on w.user_id=m.owner_id and w.id=m.work_id
 left join public.pro_time_activities a on a.owner_id=m.owner_id and a.id=m.activity_id
 left join public.pro_time_entry_people pp on pp.owner_id=m.owner_id and pp.entry_id=m.id
 left join lateral(select x.person_id,x.person_name from public.pro_work_timers x where x.owner_id=m.owner_id and x.time_entry_id=m.id limit 1) t on true
 union all
 select l.id,l.work_id,w.service,l.recorded_on,l.minutes,false,null::bigint,null::bigint,case when l.hourly_cost_cents is not null then l.amount_cents end,
  null::text,'owner','Propietario','ledger',l.note,l.created_at
 from public.pro_work_cost_entries l join public.pro_work w on w.user_id=l.user_id and w.id=l.work_id
 where l.user_id=p_actor and l.kind='time' and l.recorded_on between p_from and p_to
  and not exists(select 1 from public.pro_work_cost_entries r where r.user_id=l.user_id and r.reversal_id=l.id)
  and not exists(select 1 from public.pro_time_entries e where e.owner_id=p_actor and e.cost_entry_id is not null and (e.cost_entry_id=l.id or public.pro_time_live_line(e.owner_id,e.cost_entry_id)=l.id));
$$;

create or replace function public.pro_time_report_read(p_actor uuid,p_filters jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare first_day date;last_day date;v_work text;v_person text;v_billable text;all_rows jsonb;filtered jsonb;rows_json jsonb;totals jsonb;by_person jsonb;by_work jsonb;people jsonb;jobs jsonb;total_rows bigint;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_filters is null or jsonb_typeof(p_filters)<>'object' or not coalesce(p_filters->>'from','')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not coalesce(p_filters->>'to','')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid report query' using errcode='22023';end if;
 first_day:=(p_filters->>'from')::date;last_day:=(p_filters->>'to')::date;
 if first_day<date'1900-01-01' or last_day>date'2100-12-31' or last_day-first_day not between 0 and 366 then raise exception 'Invalid report period' using errcode='22023';end if;
 v_work:=nullif(p_filters->>'workId','');v_person:=nullif(p_filters->>'person','');v_billable:=coalesce(nullif(p_filters->>'billable',''),'all');
 if v_billable not in('all','billable','nonbillable') or length(coalesce(v_work,''))>160 or length(coalesce(v_person,''))>200 then raise exception 'Invalid report filter' using errcode='22023';end if;
 -- One pass over the ledger of the period (no temporary tables: the read stays read-only).
 select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) into all_rows from public.pro_time_report_rows(p_actor,first_day,last_day) r;
 select coalesce(jsonb_agg(x),'[]'::jsonb) into filtered from jsonb_array_elements(all_rows) x
  where (v_work is null or x->>'work_id'=v_work) and (v_person is null or x->>'person_key'=v_person)
   and (v_billable='all' or v_billable='billable' and (x->>'billable')::boolean or v_billable='nonbillable' and not (x->>'billable')::boolean);
 total_rows:=jsonb_array_length(filtered);
 select coalesce(jsonb_agg(jsonb_build_object('id',x->>'id','workId',x->>'work_id','workTitle',x->>'work_title','date',x->>'recorded_on','minutes',(x->>'minutes')::int,
   'billable',(x->>'billable')::boolean,'billableCents',(x->>'billable_cents')::bigint,'costCents',(x->>'cost_cents')::bigint,'activity',x->>'activity_name','personKey',x->>'person_key','personName',x->>'person_name','source',x->>'source','note',x->>'note')
   order by x->>'recorded_on' desc,x->>'created_at' desc,x->>'id'),'[]'::jsonb) into rows_json
  from (select x from jsonb_array_elements(filtered) x order by x->>'recorded_on' desc,x->>'created_at' desc,x->>'id' limit 1000) y;
 select jsonb_build_object('entries',count(*),'minutes',coalesce(sum((x->>'minutes')::int),0),'billableMinutes',coalesce(sum((x->>'minutes')::int) filter(where (x->>'billable')::boolean),0),
   'billableCents',coalesce(sum((x->>'billable_cents')::bigint),0),'costCents',coalesce(sum((x->>'cost_cents')::bigint),0),'uncostedMinutes',coalesce(sum((x->>'minutes')::int) filter(where x->>'cost_cents' is null),0)) into totals from jsonb_array_elements(filtered) x;
 select coalesce(jsonb_agg(jsonb_build_object('key',g.k,'name',g.n,'minutes',g.m,'billableCents',g.c) order by g.m desc,g.n),'[]'::jsonb) into by_person
  from (select x->>'person_key' k,min(x->>'person_name') n,sum((x->>'minutes')::int) m,coalesce(sum((x->>'billable_cents')::bigint),0) c from jsonb_array_elements(filtered) x group by 1) g;
 select coalesce(jsonb_agg(jsonb_build_object('workId',g.k,'title',g.n,'minutes',g.m,'billableCents',g.c) order by g.m desc,g.n),'[]'::jsonb) into by_work
  from (select x->>'work_id' k,min(x->>'work_title') n,sum((x->>'minutes')::int) m,coalesce(sum((x->>'billable_cents')::bigint),0) c from jsonb_array_elements(filtered) x group by 1) g;
 -- Filter options come from the whole period (not the filtered rows), so a filter can always be changed.
 select coalesce(jsonb_agg(jsonb_build_object('key',p.k,'name',p.n) order by p.n),'[]'::jsonb) into people
  from (select x->>'person_key' k,min(x->>'person_name') n from jsonb_array_elements(all_rows) x group by 1) p;
 select coalesce(jsonb_agg(jsonb_build_object('workId',w.id,'title',w.service) order by w.service,w.id),'[]'::jsonb) into jobs
  from (select id,service from public.pro_work where user_id=p_actor order by service,id limit 500) w;
 return jsonb_build_object('period',jsonb_build_object('from',to_char(first_day,'YYYY-MM-DD'),'to',to_char(last_day,'YYYY-MM-DD')),
  'filters',jsonb_build_object('workId',v_work,'person',v_person,'billable',v_billable),'rows',rows_json,'truncated',total_rows>1000,
  'totals',totals,'byPerson',by_person,'byWork',by_work,'people',people,'jobs',jobs);
end $$;
do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_time_report_rows','pro_time_report_read') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== pro-notifications-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): in-app notification center with per-person preferences and a
-- reminder schedule (family 24). A notification belongs to the owner's company and to ONE person (the
-- owner, or a company member working in the company through the signed role gate). Events are derived
-- idempotently from existing records (one row per person, event and source key; never duplicated):
--  task_assigned (open task whose «Responsable» is this person), task_due (open task due within the
--  person's reminder window or overdue; unassigned tasks go to the owner), client_message (customer
--  message in a job thread), quote_accepted / quote_changes (customer answer to a shared quote),
--  invoice_paid (payment applied to an invoice draft, not voided), invoice_overdue (payment plan
--  installment overdue after the grace days), bid_received (vendor bid response).
-- Email is ONLY a mock draft stored with delivery='draft_not_sent': nothing is ever sent, no push.
-- Patterns: RLS on, service_role-only, CAS 40001 on preferences, idempotent actionId receipts,
-- immutable history/receipts/drafts, America/Costa_Rica dates.
begin;
create table if not exists public.pro_notification_settings(
 owner_id uuid not null references public.profiles(id) on delete cascade,person_id uuid not null references public.profiles(id) on delete cascade,
 prefs jsonb not null default '{}'::jsonb check(jsonb_typeof(prefs)='object'),
 due_soon_days integer not null default 2 check(due_soon_days between 0 and 14),
 overdue_grace_days integer not null default 0 check(overdue_grace_days between 0 and 30),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id));
create table if not exists public.pro_notification_settings_history(
 owner_id uuid not null,person_id uuid not null,action_id uuid not null,before_row jsonb,after_row jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,action_id));
create table if not exists public.pro_notifications(
 owner_id uuid not null references public.profiles(id) on delete cascade,person_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null default gen_random_uuid(),event text not null check(event in('task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received')),
 source_key text not null check(length(source_key) between 1 and 300),
 title text not null check(length(title) between 1 and 200),body text not null default '' check(length(body)<=400),
 link jsonb not null default '{}'::jsonb check(jsonb_typeof(link)='object'),
 created_at timestamptz not null default clock_timestamp(),read_at timestamptz,
 primary key(owner_id,person_id,id),unique(owner_id,person_id,event,source_key));
create index if not exists pro_notifications_page on public.pro_notifications(owner_id,person_id,created_at desc,id desc);
create index if not exists pro_notifications_unread on public.pro_notifications(owner_id,person_id) where read_at is null;
-- Email channel = mock draft only (never sent).
create table if not exists public.pro_notification_email_drafts(
 owner_id uuid not null,person_id uuid not null,notification_id uuid not null,subject text not null,body text not null,
 delivery text not null default 'draft_not_sent' check(delivery='draft_not_sent'),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,notification_id),foreign key(owner_id,person_id,notification_id) references public.pro_notifications(owner_id,person_id,id) on delete cascade);
create table if not exists public.pro_notification_actions(
 owner_id uuid not null,person_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(owner_id,person_id,action_id));

create or replace function public.pro_notification_events() returns text[] language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received']
$$;
create or replace function public.pro_notification_person_ok(p_owner uuid,p_person uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(public.pro_private_work_tools_enabled(p_owner),false) and p_person is not null and public.pro_role_of(p_person,p_owner) is not null
$$;
create or replace function public.pro_notification_settings_json(p_owner uuid,p_person uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('revision',coalesce(s.revision,0),'dueSoonDays',coalesce(s.due_soon_days,2),'overdueGraceDays',coalesce(s.overdue_grace_days,0),
  'prefs',(select jsonb_object_agg(e,jsonb_build_object('inApp',coalesce((s.prefs->e->>'inApp')::boolean,true),'email',coalesce((s.prefs->e->>'email')::boolean,false))) from unnest(public.pro_notification_events()) e))
 from (select 1) one left join public.pro_notification_settings s on s.owner_id=p_owner and s.person_id=p_person
$$;
create or replace function public.pro_notification_enabled(p_settings jsonb,p_event text,p_channel text) returns boolean language sql immutable security invoker set search_path=public,pg_temp as $$
 select coalesce((p_settings->'prefs'->p_event->>p_channel)::boolean,p_channel='inApp')
$$;
create or replace function public.pro_notification_person_name(p_owner uuid,p_person uuid) returns text language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_person=p_owner then (select nullif(btrim(full_name),'') from public.profiles where id=p_owner)
  else (select nullif(btrim(member_name),'') from public.pro_company_members where owner_id=p_owner and member_user_id=p_person and active limit 1) end
$$;

-- Derive the person's notifications from existing records (idempotent; no duplicates; no deletes).
create or replace function public.pro_notifications_sync(p_owner uuid,p_person uuid,p_today date) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare st jsonb;who text;n integer;plan record;item jsonb;overdue jsonb:='[]'::jsonb;
begin
 if not public.pro_notification_person_ok(p_owner,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 st:=public.pro_notification_settings_json(p_owner,p_person);who:=public.pro_notification_person_name(p_owner,p_person);
 -- Overdue payment-plan installments (after the person's grace days), from the plan's own state.
 for plan in select id,work_id from public.pro_payment_plans where owner_id=p_owner and status='active' limit 200 loop
  for item in select value from jsonb_array_elements(coalesce(public.pro_payment_plan_state(p_owner,plan.id,p_today-(st->>'overdueGraceDays')::integer)->'items','[]'::jsonb)) loop
   if item->>'status'='overdue' then overdue:=overdue||jsonb_build_array(jsonb_build_object('key',plan.id::text||':'||coalesce(item->>'seq','')||':'||coalesce(item->>'dueDate',''),
    'title',left(coalesce((select service from public.pro_work where user_id=p_owner and id=plan.work_id),'Plan de pagos'),200),'body',coalesce(item->>'dueDate',''),
    'link',jsonb_build_object('tab','pro_agenda','cita',plan.work_id,'vistaTrabajo','costs','due',item->>'dueDate','amountCents',coalesce((item->>'amountCents')::bigint,0)-coalesce((item->>'appliedCents')::bigint,0))));end if;
  end loop;
 end loop;
 -- One statement, no temporary tables; only enabled in-app events become notifications; email drafts
 -- only where the person chose email (never sent).
 with events(event,source_key,title,body,link,at) as(
  -- Tasks assigned to this person (by its name as «Responsable»).
  select 'task_assigned',t.id::text||':'||lower(t.assignee),left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks'),t.updated_at
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where who is not null and t.owner_id=p_owner and not t.archived and t.status='open' and lower(btrim(t.assignee))=lower(who) and t.updated_at>clock_timestamp()-interval '60 days'
  union all
  -- Due soon / overdue tasks of this person (unassigned tasks: the owner).
  select 'task_due',t.id::text||':'||t.due_date::text,left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks','due',t.due_date::text,'overdue',t.due_date<p_today),clock_timestamp()
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where t.owner_id=p_owner and not t.archived and t.status='open' and t.due_date is not null and t.due_date<=p_today+(st->>'dueSoonDays')::integer and t.due_date>=p_today-30
    and (who is not null and lower(btrim(t.assignee))=lower(who) or btrim(t.assignee)='' and p_person=p_owner)
  union all
  -- Customer messages in job threads (last 30 days).
  select 'client_message',m.id::text,left(coalesce(nullif(m.author_name,''),'Cliente'),200),left(m.body,400),jsonb_build_object('tab','pro_agenda','cita',m.work_id,'vistaTrabajo','messages'),m.created_at
   from public.pro_work_messages m where m.owner_id=p_owner and m.side='client' and m.created_at>clock_timestamp()-interval '30 days'
  union all
  -- Customer answers to shared quotes.
  select case s.status when 'accepted' then 'quote_accepted' else 'quote_changes' end,p.id::text||':'||s.status||':'||s.revision,left(e.title,200),'',jsonb_build_object('tab','quotes','estimacionPrivada',p.estimate_id::text),p.created_at
   from public.pro_private_estimate_publications p join public.pro_private_estimate_publication_states s on s.publication_id=p.id join public.pro_private_estimates e on e.owner_id=p.owner_id and e.id=p.estimate_id
   where p.owner_id=p_owner and s.status in('accepted','changes_requested') and p.created_at>clock_timestamp()-interval '90 days'
  union all
  -- Payments applied to invoice drafts (not voided).
  select 'invoice_paid',a.id::text,left(d.title,200),a.amount_cents::text,jsonb_build_object('tab','pro_billing','amountCents',a.amount_cents),a.created_at
   from public.pro_invoice_payment_applications a join public.pro_invoice_drafts d on d.user_id=a.user_id and d.id=a.draft_id
   where a.user_id=p_owner and a.created_at>clock_timestamp()-interval '30 days' and not exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)
  union all
  select 'invoice_overdue',o->>'key',o->>'title',o->>'body',o->'link',clock_timestamp() from jsonb_array_elements(overdue) o
  union all
  -- Vendor bid responses.
  select 'bid_received',r.package_id::text||':'||r.supplier_id::text,left(b.title,200),left(coalesce((select v.name from public.pro_expense_suppliers v where v.user_id=r.owner_id and v.id=r.supplier_id),''),400),jsonb_build_object('tab','pro_agenda','cita',b.work_id,'vistaTrabajo','bids'),r.recorded_at
   from public.pro_bid_responses r join public.pro_bid_packages b on b.owner_id=r.owner_id and b.id=r.package_id
   where r.owner_id=p_owner and r.recorded_at>clock_timestamp()-interval '30 days'),
 ins as(insert into public.pro_notifications(owner_id,person_id,event,source_key,title,body,link,created_at)
  select distinct on(e.event,e.source_key) p_owner,p_person,e.event,e.source_key,e.title,e.body,e.link,least(coalesce(e.at,clock_timestamp()),clock_timestamp())
  from events e where public.pro_notification_enabled(st,e.event,'inApp')
  on conflict(owner_id,person_id,event,source_key) do nothing returning *),
 drafts as(insert into public.pro_notification_email_drafts(owner_id,person_id,notification_id,subject,body)
  select i.owner_id,i.person_id,i.id,left('ContrataCR Pro: '||i.title,200),i.title||case when i.body<>'' then E'\n'||i.body else '' end
  from ins i where public.pro_notification_enabled(st,i.event,'email') returning 1)
 select count(*) into n from ins;
 return n;
end $$;

create or replace function public.pro_notification_json(n public.pro_notifications) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',n.id,'event',n.event,'title',n.title,'body',n.body,'link',n.link,'createdAt',n.created_at,'read',n.read_at is not null,
  'emailDraft',exists(select 1 from public.pro_notification_email_drafts d where d.owner_id=n.owner_id and d.person_id=n.person_id and d.notification_id=n.id))
$$;
-- Read (syncs first): page of notifications, unread count, settings.
create or replace function public.pro_notifications_read(p_owner uuid,p_person uuid,p_filter text,p_after jsonb,p_today date) returns jsonb
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
declare rows_json jsonb;unread integer;after_at timestamptz;after_id uuid;has_more boolean;
begin
 if p_filter not in('unread','all') or p_today is null then raise exception 'Invalid notification query' using errcode='22023';end if;
 if p_after is not null then
  if jsonb_typeof(p_after)<>'object' or not coalesce(p_after->>'id','')~'^[0-9a-f-]{36}$' then raise exception 'Invalid cursor' using errcode='22023';end if;
  after_at:=(p_after->>'at')::timestamptz;after_id:=(p_after->>'id')::uuid;
 end if;
 perform public.pro_notifications_sync(p_owner,p_person,p_today);
 select count(*) into unread from public.pro_notifications where owner_id=p_owner and person_id=p_person and read_at is null;
 select coalesce(jsonb_agg(public.pro_notification_json(n) order by n.created_at desc,n.id desc),'[]'::jsonb),count(*)>30 into rows_json,has_more from (
  select * from public.pro_notifications where owner_id=p_owner and person_id=p_person and (p_filter='all' or read_at is null)
   and (after_at is null or (created_at,id)<(after_at,after_id)) order by created_at desc,id desc limit 31) n;
 if has_more then select jsonb_agg(x) into rows_json from (select x from jsonb_array_elements(rows_json) with ordinality t(x,i) where i<=30 order by i) z;end if;
 return jsonb_build_object('items',rows_json,'unread',unread,'hasMore',has_more,
  'next',case when has_more then jsonb_build_object('at',rows_json->29->>'createdAt','id',rows_json->29->>'id') end,
  'settings',public.pro_notification_settings_json(p_owner,p_person));
end $$;
-- Unread count only (header badge) — also syncs so the badge is current.
create or replace function public.pro_notifications_unread(p_owner uuid,p_person uuid,p_today date) returns integer
language plpgsql volatile security invoker set search_path=public,pg_temp as $$
begin perform public.pro_notifications_sync(p_owner,p_person,p_today);
 return (select count(*) from public.pro_notifications where owner_id=p_owner and person_id=p_person and read_at is null);end $$;

create or replace function public.pro_notifications_mutate(p_owner uuid,p_person uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;act text;hash text;prior public.pro_notification_actions;answer jsonb;cur public.pro_notification_settings;before_json jsonb;ids uuid[];changed integer:=0;p jsonb;e text;
begin
 if not public.pro_notification_person_ok(p_owner,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or not coalesce(p_input->>'actionId','')~'^[0-9a-f-]{36}$' then raise exception 'Invalid input' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;act:=p_input->>'action';hash:=encode(sha256(convert_to((p_input-'actionId')::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('pro_notifications:'||p_owner::text||':'||p_person::text,0));
 select * into prior from public.pro_notification_actions where owner_id=p_owner and person_id=p_person and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='40001';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if act in('read','unread') then
  if jsonb_typeof(p_input->'ids')<>'array' or jsonb_array_length(p_input->'ids') not between 1 and 100 then raise exception 'Invalid ids' using errcode='22023';end if;
  select array_agg(value::uuid) into ids from jsonb_array_elements_text(p_input->'ids');
  update public.pro_notifications set read_at=case when act='read' then coalesce(read_at,clock_timestamp()) else null end
   where owner_id=p_owner and person_id=p_person and id=any(ids) and (read_at is null)=(act='read');
  get diagnostics changed=row_count;
 elsif act='read_all' then
  update public.pro_notifications set read_at=clock_timestamp() where owner_id=p_owner and person_id=p_person and read_at is null;get diagnostics changed=row_count;
 elsif act='settings' then
  if not coalesce(p_input->>'revision','')~'^[0-9]+$' or jsonb_typeof(p_input->'prefs')<>'object' or not coalesce(p_input->>'dueSoonDays','')~'^[0-9]+$' or not coalesce(p_input->>'overdueGraceDays','')~'^[0-9]+$' then raise exception 'Invalid settings' using errcode='22023';end if;
  for e in select jsonb_object_keys(p_input->'prefs') loop
   if not e=any(public.pro_notification_events()) or jsonb_typeof(p_input->'prefs'->e->'inApp')<>'boolean' or jsonb_typeof(p_input->'prefs'->e->'email')<>'boolean' or (select count(*) from jsonb_object_keys(p_input->'prefs'->e))<>2 then raise exception 'Invalid preference' using errcode='22023';end if;
  end loop;
  if (p_input->>'dueSoonDays')::integer not between 0 and 14 or (p_input->>'overdueGraceDays')::integer not between 0 and 30 then raise exception 'Invalid schedule' using errcode='22023';end if;
  select * into cur from public.pro_notification_settings where owner_id=p_owner and person_id=p_person for update;
  if coalesce(cur.revision,0)<>(p_input->>'revision')::integer then raise exception 'Settings changed' using errcode='40001';end if;
  before_json:=case when cur.owner_id is null then null else public.pro_notification_settings_json(p_owner,p_person) end;
  insert into public.pro_notification_settings(owner_id,person_id,prefs,due_soon_days,overdue_grace_days,revision,updated_at)
   values(p_owner,p_person,p_input->'prefs',(p_input->>'dueSoonDays')::integer,(p_input->>'overdueGraceDays')::integer,1,clock_timestamp())
   on conflict(owner_id,person_id) do update set prefs=excluded.prefs,due_soon_days=excluded.due_soon_days,overdue_grace_days=excluded.overdue_grace_days,revision=public.pro_notification_settings.revision+1,updated_at=clock_timestamp();
  insert into public.pro_notification_settings_history(owner_id,person_id,action_id,before_row,after_row) values(p_owner,p_person,aid,before_json,public.pro_notification_settings_json(p_owner,p_person));
  changed:=1;
 else raise exception 'Invalid action' using errcode='22023';end if;
 answer:=jsonb_build_object('action',act,'changed',changed,'unread',(select count(*) from public.pro_notifications where owner_id=p_owner and person_id=p_person and read_at is null),'settings',public.pro_notification_settings_json(p_owner,p_person));
 insert into public.pro_notification_actions(owner_id,person_id,action_id,input_hash,result) values(p_owner,p_person,aid,hash,answer);
 return answer;
end $$;

create or replace function public.pro_notification_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Notification history, receipts and email drafts are immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_notification_settings','pro_notification_settings_history','pro_notifications','pro_notification_email_drafts','pro_notification_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_notification_settings_history','pro_notification_email_drafts','pro_notification_actions'] loop
  execute format('drop trigger if exists pro_notification_immutable on public.%I',t);execute format('create trigger pro_notification_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_notification_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_notification_events','pro_notification_person_ok','pro_notification_settings_json','pro_notification_enabled','pro_notification_person_name','pro_notifications_sync','pro_notification_json','pro_notifications_read','pro_notifications_unread','pro_notifications_mutate','pro_notification_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== notification-branding-capabilities-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): route capabilities of the new Round 9 routes for the role gate
-- (single source: pro_role_route_capability; same module table as job-page-local.sql plus two rules):
--  * /api/pro/notifications writes are personal ('read'): marking read and one's own preferences.
--  * /api/pro/document-branding writes are a company setting ('settings.write', Administrator only).
-- Everything else is unchanged (time-report is GET only = read; task-center bulk = work.write;
-- company-files = company.write; selections = sales.write; sub-portal stays outside the substitution).
begin;
create or replace function public.pro_role_route_capability(p_method text,p_path text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare seg text:=split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1);
begin
 if upper(coalesce(p_method,'')) in('GET','HEAD','OPTIONS') then return 'read';end if;
 -- Round 8: one's own overview arrangement is a personal preference, not a change to company data.
 if seg='overview-layout' then return 'read';end if;
 -- Round 9: the notification center (marking read, own preferences and reminder schedule) is personal.
 if seg='notifications' then return 'read';end if;
 -- Round 9: company branding of printed documents is a company setting (Administrator only).
 if seg='document-branding' then return 'settings.write';end if;
 if seg in('team','team-roles','subcontractors') then return 'team.manage';end if;
 if seg ~ '^(integrations|connectors|oauth|site|site-public|marketing|marketing-confirm|ads-tracking|social|social-content|promotions|invoice-document-settings|invoice-issuer|accounting|accounting-export|einvoice|einvoice-file)$' then return 'settings.write';end if;
 if seg ~ '^(invoice-|payment-|pay$|client-operations|client-balance|client-statement|client-finances|credits-retainers|work-billing|work-budget|work-costs|expenses|expense-receipts|purchase-order|online-payments)' then return 'finance.write';end if;
 if seg ~ '^(lead-|request-pipeline|request-followups|manual-lead-)' then return 'lead.write';end if;
 if seg ~ '^(private-estimate|quote|quotes|contract|esign|appointment-|reservations|bids|bid-portal-links|work-changes|selections|allowances|project-quote-context|visit-preparation|work-client-invitations|client-dashboard|client-pending|client-fiscal|request-quotes|direct-project|workspace|projects|work-header|identity-lookup)' then return 'sales.write';end if;
 if seg ~ '^(catalog|company-|service-packages|discount-presets|task-templates|schedule-templates|ai|ai-meetings)' then return 'company.write';end if;
 return 'work.write';
end $$;



do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_role_route_capability') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== task-center-filters-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): task center filters by job and by responsible person (row 15).
-- Same read as pro_task_center_planning_read (same counts, order, cursor and planning context) plus two
-- optional filters: p_work (one job) and p_assignee (a «Responsable» name, or '~none' for unassigned).
-- Counts follow the same filters so «Atrasadas» matches the list. Read only. Bulk reassign uses the
-- existing single task writer (pro_work_tasks_mutate 'update') from the app, one task at a time.
begin;
create or replace function public.pro_task_center_filtered_read(p_actor uuid,p_status text,p_timing text,p_query text,p_after uuid,p_work text,p_assignee text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today_cr date:=(now() at time zone 'America/Costa_Rica')::date;needle text;cursor_due date;cursor_id uuid;items jsonb;open_count integer;done_count integer;overdue_count integer;metadata jsonb;
begin
 -- Closing round: same access as the other job tools (private-work-tools-access-local.sql): an active Pro account
 -- without a directory profile also reads its task center (pro_task_center_read already did).
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('open','done','all') or p_timing is null or p_timing not in('all','overdue','today','upcoming') or p_query is null or length(p_query)>100 or length(coalesce(p_work,''))>160 or length(coalesce(p_assignee,''))>161 then raise exception 'Invalid task-center query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 -- Literal substring matching: percent/underscore never become SQL wildcards.
 select count(*) filter(where t.status='open'),count(*) filter(where t.status='done'),count(*) filter(where t.status='open' and t.due_date<today_cr)
 into open_count,done_count,overdue_count from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
 where t.owner_id=p_actor and not t.archived and public.pro_task_center_planning_matches(t,w,needle) and (p_work is null or t.work_id=p_work) and (p_assignee is null or (p_assignee='~none' and btrim(t.assignee)='') or lower(btrim(t.assignee))=lower(btrim(p_assignee)));
 if p_after is not null then
  select coalesce(t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and t.id=p_after and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle) and (p_work is null or t.work_id=p_work) and (p_assignee is null or (p_assignee='~none' and btrim(t.assignee)='') or lower(btrim(t.assignee))=lower(btrim(p_assignee)))
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end;
  if not found then raise exception 'Task-center cursor changed; refresh the list' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('task',public.pro_work_task_json(x.task),'work',jsonb_build_object('id',x.work_id,'service',x.service,'client',x.client,'stage',x.stage,'cancelled',x.cancelled)) order by (x.task).due_date asc nulls last,(x.task).id),'[]'::jsonb) into items from (
  select t as task,w.id as work_id,w.service,w.client,w.stage,coalesce(w.cancelled,false) as cancelled
  from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle) and (p_work is null or t.work_id=p_work) and (p_assignee is null or (p_assignee='~none' and btrim(t.assignee)='') or lower(btrim(t.assignee))=lower(btrim(p_assignee)))
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end
  and (p_after is null or (coalesce(t.due_date,date '9999-12-31'),t.id)>(cursor_due,p_after))
  order by t.due_date asc nulls last,t.id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'task'->>'id')::uuid;items:=items-20;end if;
 -- Resolve metadata from this exact bounded page inside the same SQL snapshot.
 select coalesce(jsonb_agg(public.pro_task_center_planning_context(t) order by i.ordinality),'[]'::jsonb) into metadata
 from jsonb_array_elements(items) with ordinality i(entry,ordinality)
 join public.pro_work_tasks t on t.owner_id=p_actor and t.id=(i.entry->'task'->>'id')::uuid and t.work_id=(i.entry->'task'->>'workId');
 return jsonb_build_object('page',jsonb_build_object('items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count,'overdue',overdue_count)),'context',metadata);
end $$;
-- Filter options: jobs with tasks and the responsible names in use (plus the owner and active members).
create or replace function public.pro_task_center_filter_options(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 -- Closing round: same access as the other job tools (private-work-tools-access-local.sql): an active Pro account
 -- without a directory profile also reads its task center (pro_task_center_read already did).
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object(
  'jobs',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'service',w.service,'client',w.client) order by w.service,w.id) from (select w.id,w.service,w.client from public.pro_work w where w.user_id=p_actor and exists(select 1 from public.pro_work_tasks t where t.owner_id=p_actor and t.work_id=w.id and not t.archived) order by w.service,w.id limit 300) w),'[]'::jsonb),
  'assignees',coalesce((select jsonb_agg(n order by lower(n)) from (select distinct on(lower(n)) n from (
     select btrim(assignee) n from public.pro_work_tasks where owner_id=p_actor and not archived and btrim(assignee)<>''
     union all select nullif(btrim(full_name),'') from public.profiles where id=p_actor
     union all select nullif(btrim(member_name),'') from public.pro_company_members where owner_id=p_actor and active) x where n is not null order by lower(n),n limit 300) y),'[]'::jsonb));
end $$;
revoke all on function public.pro_task_center_filtered_read(uuid,text,text,text,uuid,text,text),public.pro_task_center_filter_options(uuid) from public,anon,authenticated;
grant execute on function public.pro_task_center_filtered_read(uuid,text,text,text,uuid,text,text),public.pro_task_center_filter_options(uuid) to service_role;
commit;
notify pgrst,'reload schema';

-- ===== company-file-trash-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): recursive trash and restore for the company library, like the
-- job files organizer. «Enviar a la papelera» takes a folder with ALL its contents (subfolders and files)
-- out of the library in one step; «Restaurar» brings back exactly what that step took (items archived
-- before stay archived). Nothing is deleted: files, bytes and versions are untouched; only the existing
-- archived flag (with the next revision) changes. «Se puede restaurar hasta» = trash day + 30 days
-- (America/Costa_Rica); no automatic purge. If the parent folder is no longer available the folder is
-- restored at the library root. Idempotent actionId receipts, CAS 40001 on the folder revision,
-- immutable trash records. RLS + service_role-only; security invoker.
begin;
create table if not exists public.pro_company_trash(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,folder_id uuid not null,folder_name text not null,parent_id uuid,
 folders uuid[] not null,files uuid[] not null,trashed_at timestamptz not null default clock_timestamp(),restore_until date not null,
 restored_at timestamptz,restored_to_root boolean,
 primary key(owner_id,id),foreign key(owner_id,folder_id) references public.pro_company_folders(owner_id,id));
create index if not exists pro_company_trash_open on public.pro_company_trash(owner_id,trashed_at desc) where restored_at is null;
create table if not exists public.pro_company_trash_actions(
 owner_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));

create or replace function public.pro_company_trash_json(t public.pro_company_trash) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',t.id,'folderId',t.folder_id,'name',t.folder_name,'folders',cardinality(t.folders),'files',cardinality(t.files),
  'trashedAt',t.trashed_at,'restoreUntil',to_char(t.restore_until,'YYYY-MM-DD'),'restoredAt',t.restored_at,'restoredToRoot',t.restored_to_root)
$$;
create or replace function public.pro_company_trash_read(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('items',coalesce((select jsonb_agg(public.pro_company_trash_json(t) order by t.trashed_at desc,t.id) from (select * from public.pro_company_trash where owner_id=p_actor and restored_at is null order by trashed_at desc,id limit 100) t),'[]'::jsonb));
end $$;

create or replace function public.pro_company_trash_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;act text;hash text;prior public.pro_company_trash_actions;folder public.pro_company_folders;t public.pro_company_trash;sub uuid[];fls uuid[];answer jsonb;to_root boolean:=false;tid uuid;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input)<>'object' or not coalesce(p_input->>'actionId','')~'^[0-9a-f-]{36}$' then raise exception 'Invalid input' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;act:=p_input->>'action';hash:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('pro_company_files:'||p_actor::text,0));
 select * into prior from public.pro_company_trash_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 if act='trash' then
  if (select array_agg(k order by k) from jsonb_object_keys(p_input) k)<>array['action','actionId','folderId','revision'] or not coalesce(p_input->>'folderId','')~'^[0-9a-f-]{36}$' or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid trash input' using errcode='22023';end if;
  select * into folder from public.pro_company_folders where owner_id=p_actor and id=(p_input->>'folderId')::uuid for update;
  if not found then raise exception 'Folder unavailable' using errcode='42501';end if;
  if folder.archived or folder.revision<>(p_input->>'revision')::integer then raise exception 'Folder changed' using errcode='40001';end if;
  -- The whole subtree (depth ≤ 5 by the existing tree rule), only items still active.
  with recursive tree(id,depth) as(select folder.id,0 union all select f.id,tree.depth+1 from public.pro_company_folders f join tree on f.parent_id=tree.id where f.owner_id=p_actor and tree.depth<10)
  select array_agg(f.id) into sub from public.pro_company_folders f where f.owner_id=p_actor and f.id in(select id from tree) and not f.archived;
  select coalesce(array_agg(x.id),'{}') into fls from public.pro_company_files x where x.owner_id=p_actor and x.folder_id=any(sub) and not x.archived and x.ready;
  update public.pro_company_files set archived=true,revision=revision+1 where owner_id=p_actor and id=any(fls);
  update public.pro_company_folders set archived=true,revision=revision+1 where owner_id=p_actor and id=any(sub);
  tid:=gen_random_uuid();
  insert into public.pro_company_trash(owner_id,id,folder_id,folder_name,parent_id,folders,files,restore_until)
   values(p_actor,tid,folder.id,folder.name,folder.parent_id,sub,fls,(clock_timestamp() at time zone 'America/Costa_Rica')::date+30) returning * into t;
 elsif act='restore' then
  if (select array_agg(k order by k) from jsonb_object_keys(p_input) k)<>array['action','actionId','trashId'] or not coalesce(p_input->>'trashId','')~'^[0-9a-f-]{36}$' then raise exception 'Invalid restore input' using errcode='22023';end if;
  select * into t from public.pro_company_trash where owner_id=p_actor and id=(p_input->>'trashId')::uuid for update;
  if not found then raise exception 'Trash entry unavailable' using errcode='42501';end if;
  if t.restored_at is not null then raise exception 'Already restored' using errcode='40001';end if;
  -- Parent gone or archived → back at the root (never into an archived folder).
  to_root:=t.parent_id is not null and not exists(select 1 from public.pro_company_folders where owner_id=p_actor and id=t.parent_id and not archived);
  update public.pro_company_folders set archived=false,revision=revision+1,parent_id=case when id=t.folder_id and to_root then null else parent_id end where owner_id=p_actor and id=any(t.folders) and archived;
  update public.pro_company_files set archived=false,revision=revision+1 where owner_id=p_actor and id=any(t.files) and archived;
  update public.pro_company_trash set restored_at=clock_timestamp(),restored_to_root=to_root where owner_id=p_actor and id=t.id returning * into t;
 else raise exception 'Invalid action' using errcode='22023';end if;
 answer:=jsonb_build_object('action',act,'trash',public.pro_company_trash_json(t));
 insert into public.pro_company_trash_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;
-- Trash records: only the one-time restore stamp may change; receipts never change.
create or replace function public.pro_company_trash_guard() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' then raise exception 'Trash records are kept' using errcode='23514';end if;
 if tg_table_name='pro_company_trash_actions' then raise exception 'Trash receipts are immutable' using errcode='23514';end if;
 if (to_jsonb(old)->>'restored_at') is not null or (to_jsonb(new)-array['restored_at','restored_to_root']) is distinct from (to_jsonb(old)-array['restored_at','restored_to_root']) then raise exception 'Trash record immutable' using errcode='23514';end if;
 return new;
end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_company_trash','pro_company_trash_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);
  execute format('drop trigger if exists pro_company_trash_guard on public.%I',t);execute format('create trigger pro_company_trash_guard before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_company_trash_guard()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_company_trash_json','pro_company_trash_read','pro_company_trash_mutate','pro_company_trash_guard') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== subcontractor-comment-files-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): attachments in subcontractor task comments (both sides), with
-- the Round 8 message-attachment pattern: photo (PNG/WebP → JPG by the server) or PDF ≤ 20 MiB in the
-- private bucket `pro-sub-comment-files` (never public, never signed URLs). The comment is written by
-- the EXISTING writers (owner: pro_sub_owner_mutate 'comment'; subcontractor: pro_sub_portal_mutate
-- 'comment') with id = actionId = file id, so rate limits, scope checks, events and receipts are the
-- same; the file row is written in the same transaction and both are immutable. Every list and download
-- re-checks the scope in SQL at that moment: the owner of the company, or the subcontractor whose access
-- is active, whose job link is active and to whom THAT task is still assigned. Revoking access, removing
-- the job or unassigning the task stops downloads immediately. RLS + service_role-only.
begin;
create table if not exists public.pro_subcontractor_comment_files(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,comment_id uuid not null,access_id uuid not null,task_id uuid not null,
 side text not null check(side in('pro','sub')),
 name text not null check(length(name) between 1 and 160 and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 mime_type text not null check(mime_type in('image/jpeg','application/pdf')),
 size_bytes integer not null check(size_bytes between 1 and 20971520),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 object_path text not null unique,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,id),foreign key(owner_id,comment_id) references public.pro_subcontractor_comments(owner_id,id),
 check(id=comment_id),
 check(right(name,4)=case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(object_path=owner_id::text||'/'||access_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end));
create index if not exists pro_subcontractor_comment_files_scope on public.pro_subcontractor_comment_files(owner_id,access_id,task_id,created_at);

-- Who may see/write files of (owner, access, task) right now: 'pro' (the owner) or 'sub' (the active
-- subcontractor with the task assigned in an active job link); otherwise null.
create or replace function public.pro_sub_comment_scope(p_actor uuid,p_owner uuid,p_access uuid,p_task uuid) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case
  when not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then null
  when not exists(select 1 from public.pro_subcontractor_tasks st join public.pro_subcontractor_jobs j on j.owner_id=st.owner_id and j.access_id=st.access_id and j.work_id=st.work_id and j.active
    join public.pro_subcontractor_access a on a.owner_id=st.owner_id and a.id=st.access_id and a.status='active'
    join public.pro_work_tasks t on t.owner_id=st.owner_id and t.work_id=st.work_id and t.id=st.task_id and not t.archived
    where st.owner_id=p_owner and st.access_id=p_access and st.task_id=p_task and st.active) then null
  when p_actor=p_owner then 'pro'
  when exists(select 1 from public.pro_subcontractor_access a where a.owner_id=p_owner and a.id=p_access and a.member_user_id=p_actor and a.status='active') then 'sub'
  else null end
$$;
create or replace function public.pro_sub_comment_file_path(p_actor uuid,p_owner uuid,p_access uuid,p_task uuid,p_file uuid,p_mime text) returns text
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if public.pro_sub_comment_scope(p_actor,p_owner,p_access,p_task) is null then raise exception 'Forbidden' using errcode='42501';end if;
 if p_mime not in('image/jpeg','application/pdf') or p_file is null then raise exception 'Invalid file' using errcode='22023';end if;
 return p_owner::text||'/'||p_access::text||'/'||p_file::text||case when p_mime='application/pdf' then '.pdf' else '.jpg' end;
end $$;
create or replace function public.pro_sub_comment_file_json(f public.pro_subcontractor_comment_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',f.id,'commentId',f.comment_id,'taskId',f.task_id,'side',f.side,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'createdAt',f.created_at)
$$;
create or replace function public.pro_sub_comment_attach(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];own uuid;acc uuid;tid uuid;aid uuid;side text;f public.pro_subcontractor_comment_files;t public.pro_work_tasks;bytes integer;mime text;nm text;body_text text;posted jsonb;
begin
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['accessId','actionId','body','mimeType','name','ownerId','sha256','sizeBytes','taskId'] then raise exception 'Invalid attachment' using errcode='22023';end if;
 begin own:=(p_input->>'ownerId')::uuid;acc:=(p_input->>'accessId')::uuid;tid:=(p_input->>'taskId')::uuid;aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid attachment' using errcode='22023';end;
 mime:=p_input->>'mimeType';nm:=p_input->>'name';
 if mime not in('image/jpeg','application/pdf') or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false)
  or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'body') is distinct from 'string' then raise exception 'Invalid attachment' using errcode='22023';end if;
 bytes:=(p_input->>'sizeBytes')::integer;if bytes<1 or bytes>20971520 then raise exception 'File too large' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-sub-comment-file:'||p_actor::text||':'||aid::text,0));
 select * into f from public.pro_subcontractor_comment_files where owner_id=own and id=aid;
 if found then
  if f.sha256<>p_input->>'sha256' or f.access_id<>acc or f.task_id<>tid or f.name<>nm then raise exception 'Action id reused' using errcode='22023';end if;
  return jsonb_build_object('file',public.pro_sub_comment_file_json(f),'replayed',true);
 end if;
 side:=public.pro_sub_comment_scope(p_actor,own,acc,tid);if side is null then raise exception 'Forbidden' using errcode='42501';end if;
 body_text:=left(coalesce(nullif(btrim(p_input->>'body'),''),nm),1000);
 if side='pro' then
  select * into t from public.pro_work_tasks where owner_id=own and id=tid;
  posted:=public.pro_sub_owner_mutate(p_actor,jsonb_build_object('action','comment','actionId',aid,'accessId',acc,'subjectId',tid::text,'workId',t.work_id,'body',body_text));
 else
  posted:=public.pro_sub_portal_mutate(p_actor,jsonb_build_object('action','comment','actionId',aid,'accessId',acc,'ownerId',own,'taskId',tid,'body',body_text));
 end if;
 if not exists(select 1 from public.pro_subcontractor_comments where owner_id=own and id=aid and author_id=p_actor) then raise exception 'Comment not written' using errcode='40001';end if;
 insert into public.pro_subcontractor_comment_files(owner_id,id,comment_id,access_id,task_id,side,name,mime_type,size_bytes,sha256,object_path)
  values(own,aid,aid,acc,tid,side,nm,mime,bytes,p_input->>'sha256',public.pro_sub_comment_file_path(p_actor,own,acc,tid,aid,mime)) returning * into f;
 return jsonb_build_object('file',public.pro_sub_comment_file_json(f));
end $$;
-- Files of one access the actor can see now (owner: all its tasks; sub: only tasks still assigned).
create or replace function public.pro_sub_comment_files_read(p_actor uuid,p_owner uuid,p_access uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 return jsonb_build_object('files',coalesce((select jsonb_agg(public.pro_sub_comment_file_json(f) order by f.created_at,f.id) from public.pro_subcontractor_comment_files f
  where f.owner_id=p_owner and f.access_id=p_access and public.pro_sub_comment_scope(p_actor,p_owner,p_access,f.task_id) is not null),'[]'::jsonb));
end $$;
create or replace function public.pro_sub_comment_file_download(p_actor uuid,p_owner uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f public.pro_subcontractor_comment_files;
begin
 select * into f from public.pro_subcontractor_comment_files where owner_id=p_owner and id=p_file;
 if not found or public.pro_sub_comment_scope(p_actor,f.owner_id,f.access_id,f.task_id) is null then return null;end if;
 return jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
end $$;
create or replace function public.pro_sub_comment_files_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Comment attachments are immutable' using errcode='23514';end $$;
do $$declare f record;begin
 alter table public.pro_subcontractor_comment_files enable row level security;
 revoke all on public.pro_subcontractor_comment_files from public,anon,authenticated;grant select,insert,update,delete on public.pro_subcontractor_comment_files to service_role;
 drop trigger if exists pro_sub_comment_files_immutable on public.pro_subcontractor_comment_files;
 create trigger pro_sub_comment_files_immutable before update or delete on public.pro_subcontractor_comment_files for each row when (pg_trigger_depth()=0) execute function public.pro_sub_comment_files_immutable();
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_sub_comment_scope','pro_sub_comment_file_path','pro_sub_comment_file_json','pro_sub_comment_attach','pro_sub_comment_files_read','pro_sub_comment_file_download','pro_sub_comment_files_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-sub-comment-files','pro-sub-comment-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
  if not exists(select 1 from storage.buckets where id='pro-sub-comment-files' and not public and file_size_limit=20971520) then raise exception 'Sub comment files bucket configuration';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== document-branding-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): company branding of printed documents (family 45). One record
-- per company: a ContrataCR-style colour theme (fixed list, no free colours), the company name and a
-- short line for the header, a footer line, and an optional company logo (JPG normalised by the server,
-- ≤ 1 MiB, private bucket `pro-document-logos`, embedded in the printed copy; never a public URL).
-- Applies to future prints only; printed copies and documents already shared are not changed. The
-- ContrataCR mark stays as approved. CAS 40001 on the revision, idempotent actionId receipts,
-- immutable history; RLS + service_role-only. Writes are 'settings.write' for the role gate.
begin;
create table if not exists public.pro_document_branding(
 owner_id uuid primary key references public.profiles(id) on delete cascade,
 theme text not null default 'celeste' check(theme in('celeste','marino','bosque','terracota')),
 display_name text not null default '' check(length(display_name)<=120 and display_name=btrim(display_name)),
 tagline text not null default '' check(length(tagline)<=160 and tagline=btrim(tagline)),
 footer_text text not null default '' check(length(footer_text)<=300 and footer_text=btrim(footer_text)),
 logo_path text,logo_sha256 text check(logo_sha256 is null or logo_sha256~'^[a-f0-9]{64}$'),logo_bytes integer check(logo_bytes is null or logo_bytes between 1 and 1048576),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 check((logo_path is null)=(logo_sha256 is null) and (logo_path is null)=(logo_bytes is null)),
 check(logo_path is null or logo_path~('^'||owner_id::text||'/[0-9a-f-]{36}\.jpg$')));
create table if not exists public.pro_document_branding_history(
 owner_id uuid not null,action_id uuid not null,before_row jsonb,after_row jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_document_branding_actions(
 owner_id uuid not null,action_id uuid not null,input_hash text not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));

create or replace function public.pro_document_branding_json(p_owner uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('revision',coalesce(b.revision,0),'theme',coalesce(b.theme,'celeste'),'displayName',coalesce(b.display_name,''),'tagline',coalesce(b.tagline,''),'footer',coalesce(b.footer_text,''),
  'logo',case when b.logo_path is null then null else jsonb_build_object('path',b.logo_path,'sha256',b.logo_sha256,'bytes',b.logo_bytes) end)
 from (select 1) one left join public.pro_document_branding b on b.owner_id=p_owner
$$;
create or replace function public.pro_document_branding_read(p_actor uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return public.pro_document_branding_json(p_actor);
end $$;
-- Print routes: the branding of the document's owner (no access check here; the caller already
-- authorised the document itself). Returns defaults when the owner has none.
create or replace function public.pro_document_branding_for_print(p_owner uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_document_branding_json(p_owner)
$$;
create or replace function public.pro_document_branding_logo_path(p_actor uuid,p_file uuid) returns text language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_file is null then raise exception 'Invalid file' using errcode='22023';end if;
 return p_actor::text||'/'||p_file::text||'.jpg';
end $$;
create or replace function public.pro_document_branding_save(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;hash text;prior public.pro_document_branding_actions;cur public.pro_document_branding;before_json jsonb;answer jsonb;keys text[];logo jsonb;v_path text;v_sha text;v_bytes integer;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['actionId','displayName','footer','logo','revision','tagline','theme'] or not coalesce(p_input->>'actionId','')~'^[0-9a-f-]{36}$' or jsonb_typeof(p_input->'revision')<>'number' then raise exception 'Invalid branding' using errcode='22023';end if;
 if p_input->>'theme' not in('celeste','marino','bosque','terracota') or jsonb_typeof(p_input->'displayName')<>'string' or jsonb_typeof(p_input->'tagline')<>'string' or jsonb_typeof(p_input->'footer')<>'string'
  or length(p_input->>'displayName')>120 or length(p_input->>'tagline')>160 or length(p_input->>'footer')>300 then raise exception 'Invalid branding' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;hash:=encode(sha256(convert_to(p_input::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('pro_document_branding:'||p_actor::text,0));
 select * into prior from public.pro_document_branding_actions where owner_id=p_actor and action_id=aid;
 if found then if prior.input_hash<>hash then raise exception 'Action id reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into cur from public.pro_document_branding where owner_id=p_actor for update;
 if coalesce(cur.revision,0)<>(p_input->>'revision')::integer then raise exception 'Branding changed' using errcode='40001';end if;
 logo:=p_input->'logo';
 -- logo: 'keep' (string), null (remove) or {path,sha256,bytes} of a file the server just stored at the path SQL gave.
 if logo='"keep"'::jsonb then v_path:=cur.logo_path;v_sha:=cur.logo_sha256;v_bytes:=cur.logo_bytes;
 elsif jsonb_typeof(logo)='null' then v_path:=null;
 elsif jsonb_typeof(logo)='object' then
  if (select array_agg(k order by k) from jsonb_object_keys(logo) k) is distinct from array['bytes','path','sha256'] or not coalesce(logo->>'path','')~('^'||p_actor::text||'/[0-9a-f-]{36}\.jpg$') or not coalesce(logo->>'sha256','')~'^[a-f0-9]{64}$' or not coalesce(logo->>'bytes','')~'^[0-9]{1,7}$' or (logo->>'bytes')::integer not between 1 and 1048576 then raise exception 'Invalid logo' using errcode='22023';end if;
  v_path:=logo->>'path';v_sha:=logo->>'sha256';v_bytes:=(logo->>'bytes')::integer;
 else raise exception 'Invalid logo' using errcode='22023';end if;
 before_json:=case when cur.owner_id is null then null else public.pro_document_branding_json(p_actor) end;
 insert into public.pro_document_branding(owner_id,theme,display_name,tagline,footer_text,logo_path,logo_sha256,logo_bytes,revision,updated_at)
  values(p_actor,p_input->>'theme',btrim(p_input->>'displayName'),btrim(p_input->>'tagline'),btrim(p_input->>'footer'),v_path,case when v_path is null then null else v_sha end,case when v_path is null then null else v_bytes end,1,clock_timestamp())
  on conflict(owner_id) do update set theme=excluded.theme,display_name=excluded.display_name,tagline=excluded.tagline,footer_text=excluded.footer_text,logo_path=excluded.logo_path,logo_sha256=excluded.logo_sha256,logo_bytes=excluded.logo_bytes,revision=public.pro_document_branding.revision+1,updated_at=clock_timestamp();
 answer:=jsonb_build_object('branding',public.pro_document_branding_json(p_actor));
 insert into public.pro_document_branding_history(owner_id,action_id,before_row,after_row) values(p_actor,aid,before_json,answer->'branding');
 insert into public.pro_document_branding_actions(owner_id,action_id,input_hash,result) values(p_actor,aid,hash,answer);
 return answer;
end $$;
create or replace function public.pro_document_branding_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Branding history and receipts are immutable' using errcode='23514';end $$;
do $$declare t text;f record;begin
 foreach t in array array['pro_document_branding','pro_document_branding_history','pro_document_branding_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;
 foreach t in array array['pro_document_branding_history','pro_document_branding_actions'] loop
  execute format('drop trigger if exists pro_document_branding_immutable on public.%I',t);execute format('create trigger pro_document_branding_immutable before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_document_branding_immutable()',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_document_branding_json','pro_document_branding_read','pro_document_branding_for_print','pro_document_branding_logo_path','pro_document_branding_save','pro_document_branding_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-document-logos','pro-document-logos',false,1048576,array['image/jpeg']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
  if not exists(select 1 from storage.buckets where id='pro-document-logos' and not public and file_size_limit=1048576) then raise exception 'Document logos bucket configuration';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== selection-catalog-local.sql =====
-- LOCAL PRO ONLY. Round 9 (2026-11-15): selection options from the company catalog (row 62).
-- «Agregar desde el catálogo» creates a normal option through the EXISTING selections writer
-- (pro_work_selections_mutate 'option_add', option id = actionId, so a retry never duplicates) with the
-- catalog item's name, price (CRC cents) and preferred vendor (as brand), and records its source:
-- product id, a snapshot of what was copied, and a private COPY of the catalog image (bucket
-- `pro-selection-catalog-images`, SHA-256 checked) so replacing the catalog image never changes an
-- option the customer saw. The customer sees that image like any option photo (same authorisation as
-- pro_work_selection_image). Approvals, allowance links and totals are unchanged (no double counting:
-- options are not costs; only the explicit allowance decision records an amount). RLS + service_role-only.
begin;
create table if not exists public.pro_work_selection_option_sources(
 owner_id uuid not null references public.profiles(id) on delete cascade,option_id uuid not null,product_id text not null,
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
 image_path text check(image_path is null or image_path~'^[a-f0-9-]{36}/[a-f0-9-]{36}\.jpg$'),
 image_sha256 text check(image_sha256 is null or image_sha256~'^[a-f0-9]{64}$'),image_size integer check(image_size is null or image_size between 1 and 20971520),
 created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,option_id),foreign key(owner_id,option_id) references public.pro_work_selection_options(owner_id,id) on delete cascade,
 check((image_path is null)=(image_sha256 is null) and (image_path is null)=(image_size is null)),
 check(image_path is null or split_part(image_path,'/',1)=owner_id::text and split_part(image_path,'/',2)=option_id::text||'.jpg'));

-- What the server needs before copying: the catalog item (not archived), its price and vendor, and its image.
create or replace function public.pro_work_selection_catalog_prepare(p_actor uuid,p_work text,p_product text,p_option uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare p public.pro_products;d public.pro_product_details;vendor text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_option is null or p_product is null or length(p_product) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Invalid catalog option' using errcode='22023';end if;
 select * into p from public.pro_products where user_id=p_actor and id=p_product and not archived;
 if not found then return null;end if;
 select * into d from public.pro_product_details where user_id=p_actor and product_id=p_product;
 select s.name into vendor from public.pro_expense_suppliers s where s.user_id=p_actor and s.id=d.preferred_vendor_id;
 return jsonb_build_object('productId',p.id,'sku',p.sku,'name',left(p.name,160),'unit',p.unit,'unitCents',round(p.price*100)::bigint,'vendor',vendor,
  'image',case when d.image_path is null then null else jsonb_build_object('objectPath',d.image_path,'sha256',d.image_sha256,'sizeBytes',d.image_size) end,
  'targetPath',case when d.image_path is null then null else p_actor::text||'/'||p_option::text||'.jpg' end);
end $$;

create or replace function public.pro_work_selection_option_from_catalog(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare keys text[];aid uuid;prep jsonb;result jsonb;img jsonb;existing public.pro_work_selection_option_sources;
begin
 select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from array['actionId','id','image','productId','quantity','revision','workId'] or not coalesce(p_input->>'actionId','')~'^[0-9a-f-]{36}$' then raise exception 'Invalid catalog option' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('pro-selection-catalog:'||p_actor::text||':'||aid::text,0));
 select * into existing from public.pro_work_selection_option_sources where owner_id=p_actor and option_id=aid;
 if found and existing.product_id<>p_input->>'productId' then raise exception 'Action id reused' using errcode='22023';end if;
 prep:=public.pro_work_selection_catalog_prepare(p_actor,p_input->>'workId',p_input->>'productId',aid);
 if prep is null and not found then raise exception 'Catalog item unavailable' using errcode='40001';end if;
 -- The existing writer: same checks, CAS on the item revision, idempotent receipt by actionId.
 result:=public.pro_work_selections_mutate(p_actor,jsonb_build_object('action','option_add','actionId',aid,'workId',p_input->>'workId','id',p_input->>'id','revision',p_input->'revision',
  'optionId',aid,'name',coalesce(existing.snapshot->>'name',prep->>'name'),'brand',coalesce(existing.snapshot->'vendor',prep->'vendor'),'url',null,'quantity',p_input->'quantity',
  'unitCents',coalesce((existing.snapshot->>'unitCents')::bigint,(prep->>'unitCents')::bigint),'clientNotes',null,'imageFileId',null));
 if existing.option_id is null then
  img:=p_input->'image';
  if jsonb_typeof(img)='object' and (img->>'path'<>prep->>'targetPath' or not coalesce(img->>'sha256','')~'^[a-f0-9]{64}$' or not coalesce(img->>'sizeBytes','')~'^[0-9]{1,8}$') then raise exception 'Invalid image copy' using errcode='22023';end if;
  insert into public.pro_work_selection_option_sources(owner_id,option_id,product_id,snapshot,image_path,image_sha256,image_size)
   values(p_actor,aid,p_input->>'productId',prep-'image'-'targetPath',case when jsonb_typeof(img)='object' then img->>'path' end,case when jsonb_typeof(img)='object' then img->>'sha256' end,case when jsonb_typeof(img)='object' then (img->>'sizeBytes')::integer end);
 end if;
 return result; -- same answer shape as the writer (the source is read with pro_work_selection_sources_read)
end $$;
-- Owner: which options of a job came from the catalog (for the «Del catálogo» mark).
create or replace function public.pro_work_selection_sources_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('sources',coalesce((select jsonb_agg(jsonb_build_object('optionId',s.option_id,'productId',s.product_id,'sku',s.snapshot->>'sku','hasImage',s.image_path is not null) order by s.created_at)
  from public.pro_work_selection_option_sources s join public.pro_work_selection_options o on o.owner_id=s.owner_id and o.id=s.option_id where s.owner_id=p_actor and o.work_id=p_work),'[]'::jsonb));
end $$;

-- Customer view: an option with a catalog image shows it like any option photo.
create or replace function public.pro_work_selection_client_item_json(p_row public.pro_work_selection_items) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'areaId',p_row.area_id,'name',p_row.name,'dueDate',p_row.due_date,'state',public.pro_work_selection_state(p_row),
  'approvedOptionId',p_row.approved_option_id,'approvedAt',p_row.approved_at,'clientComment',p_row.client_comment,'recommendedOptionId',p_row.recommended_option_id,'revision',p_row.revision,
  'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'brand',o.brand,'url',o.url,'quantity',o.quantity,'unitCents',o.unit_cents,'totalCents',o.total_cents,
   'clientNotes',o.client_notes,'hasImage',o.image_file_id is not null or exists(select 1 from public.pro_work_selection_option_sources s where s.owner_id=o.owner_id and s.option_id=o.id and s.image_path is not null)) order by o.position) from public.pro_work_selection_options o where o.owner_id=p_row.owner_id and o.item_id=p_row.id and not o.archived),'[]'::jsonb));
$$;
-- Image of a catalog option (same authorisation as pro_work_selection_image).
create or replace function public.pro_work_selection_catalog_image(p_actor uuid,p_option uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare o public.pro_work_selection_options;i public.pro_work_selection_items;s public.pro_work_selection_option_sources;allowed boolean:=false;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into o from public.pro_work_selection_options where id=p_option and not archived and image_file_id is null;
 if not found then return null;end if;
 select * into i from public.pro_work_selection_items where owner_id=o.owner_id and id=o.item_id;
 if o.owner_id=p_actor then
  if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
  allowed:=true;
 else
  allowed:=i.published and not i.archived
   and exists(select 1 from public.pro_work_selection_areas a where a.owner_id=i.owner_id and a.id=i.area_id and not a.archived)
   and exists(select 1 from public.pro_appointment_requests r join public.pro_client_dashboards d on d.owner_id=r.owner_id and d.work_id=r.work_id
    where r.owner_id=o.owner_id and r.work_id=o.work_id and r.client_user_id=p_actor and r.status in('confirmed','completed') and d.show_selections);
 end if;
 if not allowed then return null;end if;
 select * into s from public.pro_work_selection_option_sources where owner_id=o.owner_id and option_id=o.id and image_path is not null;
 if not found then return null;end if;
 return jsonb_build_object('objectPath',s.image_path,'mimeType','image/jpeg','sizeBytes',s.image_size,'sha256',s.image_sha256);
end $$;

create or replace function public.pro_work_selection_sources_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Selection catalog sources are immutable' using errcode='23514';end $$;
do $$declare f record;begin
 alter table public.pro_work_selection_option_sources enable row level security;
 revoke all on public.pro_work_selection_option_sources from public,anon,authenticated;grant select,insert,update,delete on public.pro_work_selection_option_sources to service_role;
 drop trigger if exists pro_work_selection_sources_immutable on public.pro_work_selection_option_sources;
 create trigger pro_work_selection_sources_immutable before update on public.pro_work_selection_option_sources for each row execute function public.pro_work_selection_sources_immutable();
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('pro_work_selection_catalog_prepare','pro_work_selection_option_from_catalog','pro_work_selection_sources_read','pro_work_selection_catalog_image','pro_work_selection_client_item_json','pro_work_selection_sources_immutable') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-selection-catalog-images','pro-selection-catalog-images',false,20971520,array['image/jpeg']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
  if not exists(select 1 from storage.buckets where id='pro-selection-catalog-images' and not public) then raise exception 'Selection catalog images bucket configuration';end if;
 end if;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== sales-contacts-board-local.sql =====
-- LOCAL PRO ONLY. Round 10 (2026-11-15), Sales (Houzz Pro parity rows 05, 07, 08).
--  * Contacts (row 05): server preview of a mapped CSV/vCard import with validation and duplicate
--    detection against the owner's own customers (normalized e-mail / Costa Rica phone) and inside the
--    file; atomic, idempotent import through the existing catalog writer (pro_mutate_catalog, same
--    workspace revision CAS: a stale screen gets 40001); tags per customer; duplicate groups; merge of
--    two customers (the kept record receives the missing contact fields, notes and tags; the other one
--    is ARCHIVED, never deleted, and remembered as «combinado en»); export rows. Jobs, quotes and
--    invoices keep pointing to the record they were created with (nothing is re-linked).
--  * Pipeline board (row 07): Kanban read over the existing lead sources (manual opportunities and
--    ContrataCR requests) per configured stage; moving a card goes through the EXISTING stage writers
--    (pro_lead_center_mutate / pro_request_pipeline_mutate: their receipts, CAS and history). Stage
--    configuration (add/rename/reorder/hide with reassignment) already exists in request-pipeline.
--    New: won/lost outcome with reason and note per lead (CAS, receipts, immutable history).
--  * Conversion by channel / campaign (row 08): funnel per channel or campaign for a Costa Rica period
--    (received, reached meeting, reached estimate, won, lost, converted to a job) and monthly trend.
--  * Role gate: /api/pro/client-contacts writes are sales.write (customers).
-- Patterns: RLS on, service_role only, security invoker, CAS 40001, idempotent actionId receipts,
-- immutable history. Nothing is sent; no third party is called.
begin;
create table if not exists public.pro_contact_tags(
 owner_id uuid not null references public.profiles(id) on delete cascade,client_id text not null,
 tag text not null check(length(btrim(tag)) between 1 and 40 and tag=btrim(tag) and tag!~'[[:cntrl:];,]'),
 tag_key text generated always as (lower(tag)) stored,created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,client_id,tag_key),foreign key(owner_id,client_id) references public.pro_clients(user_id,id) on delete cascade);
create index if not exists pro_contact_tags_key on public.pro_contact_tags(owner_id,tag_key);
create table if not exists public.pro_contact_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_contact_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,client_id text not null,
 action text not null check(action in('import','tags','merge_keep','merge_archive')),before_value jsonb,after_value jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id,client_id));
create table if not exists public.pro_contact_merges(
 owner_id uuid not null references public.profiles(id) on delete cascade,merged_id text not null,kept_id text not null,action_id uuid not null,
 merged_name text not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,merged_id),check(merged_id<>kept_id));
create table if not exists public.pro_contact_imports(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 file_name text not null check(length(file_name) between 1 and 160),format text not null check(format in('csv','vcard')),
 total integer not null check(total between 1 and 500),created integer not null check(created>=0),skipped integer not null check(skipped>=0),
 created_ids text[] not null,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));

-- Lead outcome (won / lost with a reason). One current row per lead (CAS); history immutable.
create table if not exists public.pro_lead_outcomes(
 owner_id uuid not null references public.profiles(id) on delete cascade,kind text not null check(kind in('manual','request')),lead_id uuid not null,
 outcome text check(outcome in('won','lost')),reason text,note text not null default '' check(length(note)<=300),
 revision integer not null check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,kind,lead_id),
 check(outcome is null and reason is null or outcome='won' and reason in('price','quality','referral','speed','relationship','other') or outcome='lost' and reason in('price','timing','competitor','no_response','scope','other')));
create table if not exists public.pro_lead_outcome_history(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,kind text not null,lead_id uuid not null,
 before_value jsonb,after_value jsonb not null,actor_name text not null default '',at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
create table if not exists public.pro_lead_outcome_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));

create or replace function public.pro_round10_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Immutable record' using errcode='55000';end $$;
do $$declare t text;begin
 foreach t in array array['pro_contact_actions','pro_contact_history','pro_contact_merges','pro_contact_imports','pro_lead_outcome_history','pro_lead_outcome_actions'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_round10_immutable()',t||'_immutable',t);
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);
 end loop;
 foreach t in array array['pro_contact_tags','pro_lead_outcomes'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;

create or replace function public.pro_contact_owner(p_owner uuid) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin if p_owner is null or not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
create or replace function public.pro_contact_email_key(p text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select nullif(lower(btrim(coalesce(p,''))),'') $$;
create or replace function public.pro_contact_phone_key(p text) returns text language sql immutable security invoker set search_path=public,pg_temp as $$
 select nullif(public.pro_lead_import_phone_key(p),'') $$;
-- Fix 13 (performance): the import preview looks up existing customers by e-mail/phone key per row.
create index if not exists pro_clients_contact_email_key on public.pro_clients(user_id,public.pro_contact_email_key(email));
create index if not exists pro_clients_contact_phone_key on public.pro_clients(user_id,public.pro_contact_phone_key(phone));
create or replace function public.pro_contact_tags_of(p_owner uuid,p_client text) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(jsonb_agg(tag order by tag_key),'[]'::jsonb) from public.pro_contact_tags where owner_id=p_owner and client_id=p_client $$;
-- Normalized tag list (≤ 10, 1–40 characters, no control/«;»/«,», case-insensitive unique) or null when invalid.
create or replace function public.pro_contact_tag_list(p jsonb) returns text[] language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare v text;out text[]:='{}';keys text[]:='{}';
begin
 if p is null or p='null'::jsonb then return out;end if;
 if jsonb_typeof(p)<>'array' or jsonb_array_length(p)>10 then return null;end if;
 for v in select btrim(x) from jsonb_array_elements_text(p) x loop
  if length(v) not between 1 and 40 or v~'[[:cntrl:];,]' then return null;end if;
  if not lower(v)=any(keys) then out:=out||v;keys:=keys||lower(v);end if;
 end loop;return out;
exception when others then return null;end $$;

-- Preview of a mapped import (rows already mapped to ContrataCR fields by the screen).
create or replace function public.pro_contacts_preview(p_owner uuid,p_rows jsonb) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r jsonb;i integer:=-1;answer jsonb:='[]';seen_e text[]:='{}';seen_p text[]:='{}';issues text[];v_name text;v_email text;v_phone text;v_ident text;ek text;pk text;tags text[];
 m_id text;m_name text;m_by text;status text;n_new integer:=0;n_dup integer:=0;n_file integer:=0;n_bad integer:=0;f text;
begin
 perform public.pro_contact_owner(p_owner);
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) not between 1 and 500 then raise exception 'Invalid contact rows' using errcode='22023';end if;
 for r in select value from jsonb_array_elements(p_rows) loop
  i:=i+1;issues:='{}';
  if jsonb_typeof(r) is distinct from 'object' or (r-array['name','email','phone','identification','tradeName','group','address','notes','tags'])<>'{}'::jsonb then raise exception 'Invalid contact row' using errcode='22023';end if;
  foreach f in array array['name','email','phone','identification','tradeName','group','address','notes'] loop
   if r ? f and jsonb_typeof(r->f) is distinct from 'string' then raise exception 'Invalid contact field' using errcode='22023';end if;end loop;
  v_name:=btrim(coalesce(r->>'name',''));v_email:=btrim(coalesce(r->>'email',''));v_phone:=btrim(coalesce(r->>'phone',''));v_ident:=regexp_replace(coalesce(r->>'identification',''),'[^0-9]','','g');
  if v_name='' then issues:=issues||'name_required'::text;elsif length(v_name)>160 or v_name~'[[:cntrl:]]' then issues:=issues||'name_invalid'::text;end if;
  if v_email<>'' and(length(v_email)>254 or v_email!~'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') then issues:=issues||'email_invalid'::text;end if;
  if length(v_phone)>30 then issues:=issues||'phone_invalid'::text;end if;
  if length(v_ident)>12 then issues:=issues||'identification_invalid'::text;end if;
  if length(btrim(coalesce(r->>'tradeName','')))>160 or length(btrim(coalesce(r->>'group','')))>80 or length(btrim(coalesce(r->>'address','')))>500 or length(btrim(coalesce(r->>'notes','')))>2000 then issues:=issues||'too_long'::text;end if;
  tags:=public.pro_contact_tag_list(r->'tags');if tags is null then issues:=issues||'tags_invalid'::text;tags:='{}';end if;
  ek:=public.pro_contact_email_key(v_email);pk:=public.pro_contact_phone_key(v_phone);m_id:=null;m_name:=null;m_by:=null;
  if cardinality(issues)>0 then status:='invalid';n_bad:=n_bad+1;
  else
   select c.id,c.name,case when ek is not null and public.pro_contact_email_key(c.email)=ek then 'email' else 'phone' end into m_id,m_name,m_by from public.pro_clients c
    where c.user_id=p_owner and(ek is not null and public.pro_contact_email_key(c.email)=ek or pk is not null and public.pro_contact_phone_key(c.phone)=pk) order by c.archived,c.position limit 1;
   if m_id is not null then status:='duplicate';n_dup:=n_dup+1;
   elsif ek=any(seen_e) or pk=any(seen_p) then status:='duplicate_in_file';n_file:=n_file+1;
   else status:='new';n_new:=n_new+1;if ek is not null then seen_e:=seen_e||ek;end if;if pk is not null then seen_p:=seen_p||pk;end if;end if;
  end if;
  answer:=answer||jsonb_build_array(jsonb_build_object('index',i,'status',status,'issues',to_jsonb(issues),
   'row',jsonb_build_object('name',v_name,'email',v_email,'phone',v_phone,'identification',v_ident,'tradeName',btrim(coalesce(r->>'tradeName','')),'group',btrim(coalesce(r->>'group','')),'address',btrim(coalesce(r->>'address','')),'notes',btrim(coalesce(r->>'notes','')),'tags',to_jsonb(tags)),
   'match',case when m_id is null then null else jsonb_build_object('id',m_id,'name',m_name,'by',m_by) end));
 end loop;
 return jsonb_build_object('rows',answer,'counts',jsonb_build_object('total',i+1,'new',n_new,'duplicate',n_dup,'duplicateInFile',n_file,'invalid',n_bad));
end $$;

create or replace function public.pro_contacts_read(p_owner uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 perform public.pro_contact_owner(p_owner);
 return jsonb_build_object(
  'revision',coalesce((select revision from public.pro_workspace_core where user_id=p_owner),0),
  'tags',coalesce((select jsonb_object_agg(client_id,tags) from(select client_id,jsonb_agg(tag order by tag_key) tags from public.pro_contact_tags where owner_id=p_owner group by client_id)x),'{}'::jsonb),
  'tagCounts',coalesce((select jsonb_agg(jsonb_build_object('tag',tag,'count',n) order by lower(tag)) from(select min(tag) tag,count(*) n from public.pro_contact_tags t join public.pro_clients c on c.user_id=t.owner_id and c.id=t.client_id and not c.archived where t.owner_id=p_owner group by t.tag_key)x),'[]'::jsonb),
  'merges',coalesce((select jsonb_agg(jsonb_build_object('mergedId',merged_id,'keptId',kept_id,'mergedName',merged_name,'at',at) order by at desc) from(select * from public.pro_contact_merges where owner_id=p_owner order by at desc limit 100)x),'[]'::jsonb),
  'imports',coalesce((select jsonb_agg(jsonb_build_object('id',action_id,'fileName',file_name,'format',format,'total',total,'created',created,'skipped',skipped,'at',at) order by at desc) from(select * from public.pro_contact_imports where owner_id=p_owner order by at desc limit 10)x),'[]'::jsonb),
  'duplicates',public.pro_contacts_duplicates(p_owner));
end $$;

-- Rows that point to a customer (every foreign key to pro_clients except tags, plus jobs). A customer
-- with records is never archived by a merge: it must be the one that is kept.
create or replace function public.pro_contact_references(p_owner uuid,p_client text) returns integer language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f record;n integer:=0;hit boolean;
begin
 select count(*) into n from public.pro_work where user_id=p_owner and "clientId"=p_client;
 for f in select c.conrelid::regclass rel,(select attname from pg_attribute where attrelid=c.conrelid and attnum=c.conkey[1]) owner_col,(select attname from pg_attribute where attrelid=c.conrelid and attnum=c.conkey[2]) client_col
  from pg_constraint c where c.contype='f' and c.confrelid='public.pro_clients'::regclass and c.conrelid<>'public.pro_contact_tags'::regclass and cardinality(c.conkey)=2 loop
  execute format('select exists(select 1 from %s where %I=$1 and %I=$2)',f.rel,f.owner_col,f.client_col) into hit using p_owner,p_client;
  if hit then n:=n+1;end if;
 end loop;
 return n;
end $$;

-- Groups of active customers sharing a normalized e-mail or phone (≤ 50 groups).
create or replace function public.pro_contacts_duplicates(p_owner uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 with keyed as(select id,name,email,phone,position,public.pro_contact_email_key(email) ek,public.pro_contact_phone_key(phone) pk from public.pro_clients where user_id=p_owner and not archived),
 groups as(select 'email' by,ek k from keyed where ek is not null group by ek having count(*)>1 union all select 'phone',pk from keyed where pk is not null group by pk having count(*)>1)
 select coalesce(jsonb_agg(jsonb_build_object('by',g.by,'key',g.k,'clients',(select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'email',x.email,'phone',x.phone,'records',public.pro_contact_references(p_owner,x.id)) order by x.position) from keyed x where case g.by when 'email' then x.ek=g.k else x.pk=g.k end)) order by g.by,g.k),'[]'::jsonb)
 from(select * from groups order by by,k limit 50) g $$;

create or replace function public.pro_contacts_export(p_owner uuid,p_tag text default null,p_group text default null,p_archived boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 perform public.pro_contact_owner(p_owner);
 if length(coalesce(p_tag,''))>40 or length(coalesce(p_group,''))>80 then raise exception 'Invalid export filter' using errcode='22023';end if;
 -- Fix 13: bounded export (first 5000 customers in list order).
 return coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'email',c.email,'phone',c.phone,'identification',coalesce(c.identification,''),'tradeName',coalesce(c."tradeName",''),'group',coalesce(c."group",''),'address',coalesce(c.address,''),'notes',c.notes,'archived',c.archived,'tags',public.pro_contact_tags_of(p_owner,c.id),
   'mergedInto',(select m.kept_id from public.pro_contact_merges m where m.owner_id=p_owner and m.merged_id=c.id)) order by c.position)
  from (select x.* from public.pro_clients x where x.user_id=p_owner and(p_archived or not x.archived)
   and(nullif(btrim(coalesce(p_tag,'')),'') is null or exists(select 1 from public.pro_contact_tags t where t.owner_id=p_owner and t.client_id=x.id and t.tag_key=lower(btrim(p_tag))))
   and(nullif(btrim(coalesce(p_group,'')),'') is null or lower(btrim(coalesce(x."group",'')))=lower(btrim(p_group))) order by x.position limit 5000) c),'[]'::jsonb);
end $$;

create or replace function public.pro_contacts_mutate(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;keys text[];receipt public.pro_contact_actions;answer jsonb;preview jsonb;r jsonb;rows_json jsonb:='[]';ids text[]:='{}';cid text;v integer;tags text[];t text;
 keep public.pro_clients;dup public.pro_clients;kept jsonb;merged jsonb;before_tags jsonb;
begin
 perform public.pro_contact_owner(p_owner);
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid contact action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(k order by k) into keys from jsonb_object_keys(p_input) k;
 if keys is distinct from (case act when 'import' then array['action','actionId','fileName','format','revision','rows'] when 'tags' then array['action','actionId','clientId','tags'] when 'merge' then array['action','actionId','keepId','mergeId','revision'] end) then raise exception 'Unexpected contact fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 if act in('import','merge') and(jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483646) then raise exception 'Invalid revision' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-contacts:'||p_owner::text,0));
 select * into receipt from public.pro_contact_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 if act='import' then
  if jsonb_typeof(p_input->'fileName') is distinct from 'string' or length(btrim(p_input->>'fileName')) not between 1 and 160 or p_input->>'format' not in('csv','vcard') then raise exception 'Invalid import file' using errcode='22023';end if;
  preview:=public.pro_contacts_preview(p_owner,p_input->'rows');
  for r in select value from jsonb_array_elements(preview->'rows') loop
   if r->>'status'='new' then
    cid:=public.pro_lead_import_uuid('pro-contacts:'||aid::text||':'||(r->>'index'))::text;ids:=ids||cid;
    rows_json:=rows_json||jsonb_build_array(jsonb_build_object('id',cid,'name',r->'row'->>'name','email',r->'row'->>'email','phone',r->'row'->>'phone','notes',r->'row'->>'notes','archived',false,
     'identification',nullif(r->'row'->>'identification',''),'tradeName',nullif(r->'row'->>'tradeName',''),'group',nullif(r->'row'->>'group',''),'address',nullif(r->'row'->>'address','')));
   end if;
  end loop;
  if cardinality(ids)>0 then v:=public.pro_mutate_catalog(p_owner,'clients',rows_json,(p_input->>'revision')::integer,'[]'::jsonb,true);
  else v:=coalesce((select revision from public.pro_workspace_core where user_id=p_owner),0);if v<>(p_input->>'revision')::integer then raise exception 'Customers changed' using errcode='40001';end if;end if;
  for r in select value from jsonb_array_elements(preview->'rows') where value->>'status'='new' loop
   cid:=public.pro_lead_import_uuid('pro-contacts:'||aid::text||':'||(r->>'index'))::text;
   insert into public.pro_contact_tags(owner_id,client_id,tag) select p_owner,cid,x from jsonb_array_elements_text(r->'row'->'tags') x on conflict do nothing;
   insert into public.pro_contact_history(owner_id,action_id,client_id,action,before_value,after_value) values(p_owner,aid,cid,'import',null,r->'row');
  end loop;
  insert into public.pro_contact_imports(owner_id,action_id,file_name,format,total,created,skipped,created_ids) values(p_owner,aid,btrim(p_input->>'fileName'),p_input->>'format',(preview->'counts'->>'total')::integer,cardinality(ids),(preview->'counts'->>'total')::integer-cardinality(ids),ids);
  answer:=jsonb_build_object('action','import','revision',v,'created',cardinality(ids),'createdIds',to_jsonb(ids),'counts',preview->'counts');
 elsif act='tags' then
  if jsonb_typeof(p_input->'clientId') is distinct from 'string' or not exists(select 1 from public.pro_clients where user_id=p_owner and id=p_input->>'clientId') then raise exception 'Customer unavailable' using errcode='P0002';end if;
  tags:=public.pro_contact_tag_list(p_input->'tags');if tags is null then raise exception 'Invalid tags' using errcode='22023';end if;
  cid:=p_input->>'clientId';before_tags:=public.pro_contact_tags_of(p_owner,cid);
  delete from public.pro_contact_tags where owner_id=p_owner and client_id=cid;
  foreach t in array tags loop insert into public.pro_contact_tags(owner_id,client_id,tag) values(p_owner,cid,t);end loop;
  insert into public.pro_contact_history(owner_id,action_id,client_id,action,before_value,after_value) values(p_owner,aid,cid,'tags',before_tags,public.pro_contact_tags_of(p_owner,cid));
  answer:=jsonb_build_object('action','tags','clientId',cid,'tags',public.pro_contact_tags_of(p_owner,cid));
 else
  if jsonb_typeof(p_input->'keepId') is distinct from 'string' or jsonb_typeof(p_input->'mergeId') is distinct from 'string' or p_input->>'keepId'=p_input->>'mergeId' then raise exception 'Choose two customers' using errcode='22023';end if;
  select * into keep from public.pro_clients where user_id=p_owner and id=p_input->>'keepId';select * into dup from public.pro_clients where user_id=p_owner and id=p_input->>'mergeId';
  if keep.id is null or dup.id is null then raise exception 'Customer unavailable' using errcode='P0002';end if;
  if keep.archived or dup.archived or exists(select 1 from public.pro_contact_merges where owner_id=p_owner and merged_id in(keep.id,dup.id)) then raise exception 'Customers changed' using errcode='40001';end if;
  -- Jobs, quotes, invoices, leads… keep their customer: a record with any of them is never archived.
  if public.pro_contact_references(p_owner,dup.id)>0 then raise exception 'Customer to archive has records' using errcode='22023',hint='pro_contact_merge_records';end if;
  kept:=to_jsonb(keep)-'position'-'user_id';merged:=to_jsonb(dup)-'position'-'user_id';
  kept:=kept||jsonb_build_object(
   'email',case when btrim(keep.email)='' then dup.email else keep.email end,'phone',case when btrim(keep.phone)='' then dup.phone else keep.phone end,
   'identification',coalesce(nullif(keep.identification,''),nullif(dup.identification,'')),'tradeName',coalesce(nullif(keep."tradeName",''),nullif(dup."tradeName",'')),
   'group',coalesce(nullif(keep."group",''),nullif(dup."group",'')),'address',coalesce(nullif(keep.address,''),nullif(dup.address,'')),
   'notes',left(case when btrim(dup.notes)='' or position(btrim(dup.notes) in keep.notes)>0 then keep.notes when btrim(keep.notes)='' then dup.notes else keep.notes||E'\n'||dup.notes end,2000));
  v:=public.pro_mutate_catalog(p_owner,'clients',jsonb_build_array(kept,merged||jsonb_build_object('archived',true)),(p_input->>'revision')::integer,'[]'::jsonb,false);
  before_tags:=public.pro_contact_tags_of(p_owner,keep.id);
  insert into public.pro_contact_tags(owner_id,client_id,tag) select p_owner,keep.id,tag from public.pro_contact_tags where owner_id=p_owner and client_id=dup.id
   and(select count(*) from public.pro_contact_tags where owner_id=p_owner and client_id=keep.id)<10 on conflict do nothing;
  insert into public.pro_contact_merges(owner_id,merged_id,kept_id,action_id,merged_name) values(p_owner,dup.id,keep.id,aid,dup.name);
  insert into public.pro_contact_history(owner_id,action_id,client_id,action,before_value,after_value) values
   (p_owner,aid,keep.id,'merge_keep',to_jsonb(keep)-'position'||jsonb_build_object('tags',before_tags),kept||jsonb_build_object('tags',public.pro_contact_tags_of(p_owner,keep.id),'mergedFrom',dup.id)),
   (p_owner,aid,dup.id,'merge_archive',to_jsonb(dup)-'position',merged||jsonb_build_object('archived',true,'mergedInto',keep.id));
  answer:=jsonb_build_object('action','merge','revision',v,'keepId',keep.id,'mergeId',dup.id);
 end if;
 insert into public.pro_contact_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- ===== Pipeline board and outcomes =====
create or replace function public.pro_lead_outcome_json(p_owner uuid,p_kind text,p_id uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('outcome',o.outcome,'reason',o.reason,'note',coalesce(o.note,''),'revision',coalesce(o.revision,0),'updatedAt',o.updated_at)
 from(select 1) one left join public.pro_lead_outcomes o on o.owner_id=p_owner and o.kind=p_kind and o.lead_id=p_id $$;

create or replace function public.pro_lead_board_read(p_owner uuid,p_query text default '',p_channel text default null,p_hide_lost boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare catalog jsonb;answer jsonb;
begin
 perform public.pro_lead_origin_owner(p_owner);catalog:=public.pro_lead_origin_stage_catalog(p_owner);
 if p_query is null or length(p_query)>100 or length(coalesce(p_channel,''))>40 then raise exception 'Invalid board query' using errcode='22023';end if;
 with src as materialized(select s.* from public.pro_lead_inbox_sources(p_owner,p_query) s where not s.archived and not s.snoozed and(p_channel is null or p_channel='unspecified' and s.channel_id is null or s.channel_id=p_channel)),
 cards as materialized(select s.kind,s.id,s.created_at,s.effective_stage,s.channel_id,s.created_day,o.outcome,o.reason,
   case when s.kind='manual' then l.title else q.service end title,case when s.kind='manual' then c.name else q.client_name end client_name,
   case when s.kind='manual' then l.revision else coalesce(ps.revision,0) end revision,case when s.kind='manual' then l.stage_mode else coalesce(ps.mode,'automatic') end stage_mode,
   case when s.kind='manual' then l.currency end currency,case when s.kind='manual' then l.revenue_cents end revenue_cents,coalesce(o.revision,0) outcome_revision,
   row_number() over(partition by s.effective_stage order by s.created_at desc,s.kind,s.id desc) rn
  from src s left join public.pro_lead_center_records l on s.kind='manual' and l.owner_id=p_owner and l.kind='manual' and l.id=s.id left join public.pro_clients c on c.user_id=p_owner and c.id=l.client_id
   left join public.pro_appointment_requests q on s.kind='request' and q.owner_id=p_owner and q.id=s.id left join public.pro_request_pipeline_states ps on s.kind='request' and ps.owner_id=p_owner and ps.request_id=s.id
   left join public.pro_lead_outcomes o on o.owner_id=p_owner and o.kind=s.kind and o.lead_id=s.id
  where not(p_hide_lost and coalesce(o.outcome,'')='lost'))
 select jsonb_build_object('catalog',catalog,'columns',coalesce(jsonb_agg(jsonb_build_object('stageId',st->>'id','count',(select count(*) from cards x where x.effective_stage=st->>'id'),
   'items',coalesce((select jsonb_agg(jsonb_build_object('kind',x.kind,'id',x.id,'title',coalesce(x.title,''),'clientName',coalesce(x.client_name,''),'createdDay',x.created_day,'channelId',x.channel_id,'revision',x.revision,'stageMode',x.stage_mode,
     'currency',x.currency,'revenueCents',x.revenue_cents,'outcome',x.outcome,'reason',x.reason,'outcomeRevision',x.outcome_revision) order by x.rn) from cards x where x.effective_stage=st->>'id' and x.rn<=50),'[]'::jsonb)) order by(st->>'position')::integer),'[]'::jsonb),
   'lost',(select count(*) from cards where outcome='lost'))
 into answer from jsonb_array_elements(catalog->'stages') st where not coalesce((st->>'hidden')::boolean,false);
 return answer;
end $$;

-- Move a card: delegates to the existing stage writer of its source (same receipts, CAS and history).
-- Fix 13: p_member = the company member acting in the owner's company (history names that person).
drop function if exists public.pro_lead_board_mutate(uuid,jsonb);
create or replace function public.pro_lead_board_mutate(p_owner uuid,p_input jsonb,p_member uuid default null) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;k text;lid uuid;receipt public.pro_lead_outcome_actions;cur public.pro_lead_outcomes;before_json jsonb;answer jsonb;v_outcome text;v_reason text;v_note text;inner_result jsonb;
begin
 perform public.pro_lead_origin_owner(p_owner);
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid board action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from (case act when 'move' then array['action','actionId','catalogRevision','id','kind','revision','stageId'] when 'outcome' then array['action','actionId','id','kind','note','outcome','reason','revision'] end)
  or p_input->>'kind' not in('manual','request') or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483646 then raise exception 'Unexpected board fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;lid:=(p_input->>'id')::uuid;exception when others then raise exception 'Invalid identity' using errcode='22023';end;
 k:=p_input->>'kind';
 if k='manual' and not exists(select 1 from public.pro_lead_center_records where owner_id=p_owner and kind='manual' and id=lid) or k='request' and not exists(select 1 from public.pro_appointment_requests where owner_id=p_owner and id=lid) then raise exception 'Lead unavailable' using errcode='P0002';end if;
 if act='move' then
  if jsonb_typeof(p_input->'stageId') is distinct from 'string' then raise exception 'Invalid stage' using errcode='22023';end if;
  if k='manual' then inner_result:=public.pro_lead_center_mutate(p_owner,jsonb_build_object('action','set_stage','actionId',aid,'kind','manual','id',lid,'revision',(p_input->>'revision')::integer,'catalogRevision',p_input->'catalogRevision','stageId',p_input->>'stageId'));
  else inner_result:=public.pro_request_pipeline_mutate(p_owner,jsonb_build_object('action','set_stage','actionId',aid,'catalogRevision',p_input->'catalogRevision','requestId',lid,'revision',(p_input->>'revision')::integer,'stageId',p_input->>'stageId'));end if;
  return jsonb_build_object('action','move','kind',k,'id',lid,'stageId',p_input->>'stageId','revision',case when k='manual' then(inner_result->'item'->'manual'->>'revision')::integer else(inner_result->'state'->>'revision')::integer end);
 end if;
 if jsonb_typeof(p_input->'outcome') not in('string','null') or jsonb_typeof(p_input->'reason') not in('string','null') or jsonb_typeof(p_input->'note') is distinct from 'string' or length(p_input->>'note')>300 then raise exception 'Invalid outcome' using errcode='22023';end if;
 v_outcome:=p_input->>'outcome';v_reason:=p_input->>'reason';v_note:=btrim(p_input->>'note');
 if v_outcome is null and(v_reason is not null or v_note<>'') or v_outcome='won' and v_reason not in('price','quality','referral','speed','relationship','other') or v_outcome='lost' and v_reason not in('price','timing','competitor','no_response','scope','other') or v_outcome not in('won','lost') then raise exception 'Invalid outcome reason' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-outcome:'||p_owner::text||':'||aid::text,0));
 select * into receipt from public.pro_lead_outcome_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 -- Fix 13: serialize per lead BEFORE reading the revision, so two first writes (revision 0) give one 409.
 perform pg_advisory_xact_lock(hashtextextended('pro-lead-outcome-target:'||p_owner::text||':'||k||':'||lid::text,0));
 select * into cur from public.pro_lead_outcomes where owner_id=p_owner and kind=k and lead_id=lid for update;
 if coalesce(cur.revision,0)<>(p_input->>'revision')::integer then raise exception 'Outcome changed' using errcode='40001';end if;
 before_json:=public.pro_lead_outcome_json(p_owner,k,lid);
 insert into public.pro_lead_outcomes(owner_id,kind,lead_id,outcome,reason,note,revision) values(p_owner,k,lid,v_outcome,v_reason,v_note,1)
  on conflict(owner_id,kind,lead_id) do update set outcome=excluded.outcome,reason=excluded.reason,note=excluded.note,revision=public.pro_lead_outcomes.revision+1,updated_at=clock_timestamp();
 answer:=jsonb_build_object('action','outcome','kind',k,'id',lid,'value',public.pro_lead_outcome_json(p_owner,k,lid));
 insert into public.pro_lead_outcome_history(owner_id,action_id,kind,lead_id,before_value,after_value,actor_name) values(p_owner,aid,k,lid,before_json,answer->'value',left(coalesce(public.pro_team_name(case when p_member is not null and public.pro_role_of(p_member,p_owner) is not null then p_member else p_owner end),''),160));
 insert into public.pro_lead_outcome_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- ===== Conversion by channel / campaign for a Costa Rica period =====
create or replace function public.pro_lead_conversion_report(p_owner uuid,p_from date,p_to date,p_group text default 'channel') returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare catalog jsonb;meeting_pos integer;estimate_pos integer;answer jsonb;
begin
 perform public.pro_lead_origin_owner(p_owner);
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>3660 or p_from<date'1900-01-01' or p_to>date'2100-12-31' or p_group not in('channel','campaign') then raise exception 'Invalid conversion report' using errcode='22023';end if;
 catalog:=public.pro_lead_origin_stage_catalog(p_owner);
 select(s->>'position')::integer into meeting_pos from jsonb_array_elements(catalog->'stages') s where s->>'id'='meeting_scheduled';
 select(s->>'position')::integer into estimate_pos from jsonb_array_elements(catalog->'stages') s where s->>'id'='estimate_sent';
 with base as materialized(
  select b.kind,b.id,b.created_day,b.channel_id,b.archived,(select(s->>'position')::integer from jsonb_array_elements(catalog->'stages') s where s->>'id'=b.effective_stage) pos,b.effective_stage,
   case when b.kind='manual' then exists(select 1 from public.pro_manual_lead_works m join public.pro_work w on w.user_id=m.owner_id and w.id=m.work_id_text and w."clientId"=m.source_client_id and w."bookingClientId" is null where m.owner_id=p_owner and m.lead_kind='manual' and m.lead_id=b.id)
    else exists(select 1 from public.pro_appointment_requests q join public.pro_work w on w.user_id=p_owner and w.id=q.work_id where q.owner_id=p_owner and q.id=b.id and not w.cancelled) end converted,
   o.outcome,a.campaign_id
  from public.pro_lead_inbox_sources(p_owner,'') b left join public.pro_lead_outcomes o on o.owner_id=p_owner and o.kind=b.kind and o.lead_id=b.id
   left join public.pro_lead_attributions a on b.kind='manual' and a.owner_id=p_owner and a.lead_id=b.id
  where b.created_day between p_from and p_to),
 keyed as(select x.*,case when p_group='channel' then coalesce(x.channel_id,'unspecified') else coalesce(x.campaign_id::text,'none') end gkey from base x),
 grouped as(select gkey,count(*) received,count(*) filter(where pos>=meeting_pos or converted) meeting,count(*) filter(where pos>=estimate_pos or converted) estimate,
   count(*) filter(where effective_stage='won' or outcome='won' or converted) won,count(*) filter(where outcome='lost') lost,count(*) filter(where converted) converted from keyed group by gkey),
 months as(select to_char(date_trunc('month',created_day),'YYYY-MM') mon,count(*) received,count(*) filter(where converted) converted from base group by 1)
 select jsonb_build_object('from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),'group',p_group,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('key',g.gkey,
    'name',case when p_group='channel' then(select c.name from public.pro_lead_origin_catalog(p_owner) c where c.id=g.gkey) else(select ac.name from public.pro_ad_campaigns ac where ac.owner_id=p_owner and ac.id::text=g.gkey) end,
    'campaignChannel',case when p_group='campaign' then(select ac.channel from public.pro_ad_campaigns ac where ac.owner_id=p_owner and ac.id::text=g.gkey) end,
    'received',g.received,'meeting',g.meeting,'estimate',g.estimate,'won',g.won,'lost',g.lost,'converted',g.converted,
    'conversionRate',case when g.received=0 then null else round(g.converted*100.0/g.received,1) end) order by g.received desc,g.gkey) from grouped g),'[]'::jsonb),
  'totals',(select jsonb_build_object('received',count(*),'meeting',count(*) filter(where pos>=meeting_pos or converted),'estimate',count(*) filter(where pos>=estimate_pos or converted),'won',count(*) filter(where effective_stage='won' or outcome='won' or converted),'lost',count(*) filter(where outcome='lost'),'converted',count(*) filter(where converted)) from base),
  'months',coalesce((select jsonb_agg(jsonb_build_object('month',mon,'received',received,'converted',converted) order by mon) from months),'[]'::jsonb))
 into answer;
 return answer;
end $$;

-- ===== Role gate: same module table as notification-branding-capabilities-local.sql + client-contacts =====
create or replace function public.pro_role_route_capability(p_method text,p_path text) returns text
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
declare seg text:=split_part(regexp_replace(coalesce(p_path,''),'^/api/pro/?',''),'/',1);
begin
 if upper(coalesce(p_method,'')) in('GET','HEAD','OPTIONS') then return 'read';end if;
 -- Round 8: one's own overview arrangement is a personal preference, not a change to company data.
 if seg='overview-layout' then return 'read';end if;
 -- Round 9: the notification center (marking read, own preferences and reminder schedule) is personal.
 if seg='notifications' then return 'read';end if;
 -- Round 9: company branding of printed documents is a company setting (Administrator only).
 if seg='document-branding' then return 'settings.write';end if;
 -- Round 10: customer import, tags and merges are customer records (same capability as quotes/contracts).
 if seg='client-contacts' then return 'sales.write';end if;
 if seg in('team','team-roles','subcontractors') then return 'team.manage';end if;
 if seg ~ '^(integrations|connectors|oauth|site|site-public|marketing|marketing-confirm|ads-tracking|social|social-content|promotions|invoice-document-settings|invoice-issuer|accounting|accounting-export|einvoice|einvoice-file)$' then return 'settings.write';end if;
 if seg ~ '^(invoice-|payment-|pay$|client-operations|client-balance|client-statement|client-finances|credits-retainers|work-billing|work-budget|work-costs|expenses|expense-receipts|purchase-order|online-payments)' then return 'finance.write';end if;
 if seg ~ '^(lead-|request-pipeline|request-followups|manual-lead-)' then return 'lead.write';end if;
 if seg ~ '^(private-estimate|quote|quotes|contract|esign|appointment-|reservations|bids|bid-portal-links|work-changes|selections|allowances|project-quote-context|visit-preparation|work-client-invitations|client-dashboard|client-pending|client-fiscal|request-quotes|direct-project|workspace|projects|work-header|identity-lookup)' then return 'sales.write';end if;
 if seg ~ '^(catalog|company-|service-packages|discount-presets|task-templates|schedule-templates|ai|ai-meetings)' then return 'company.write';end if;
 return 'work.write';
end $$;

do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_round10_immutable','pro_contact_owner','pro_contact_email_key','pro_contact_phone_key','pro_contact_tags_of','pro_contact_tag_list','pro_contacts_preview','pro_contacts_read','pro_contacts_duplicates','pro_contact_references','pro_contacts_export','pro_contacts_mutate',
  'pro_lead_outcome_json','pro_lead_board_read','pro_lead_board_mutate','pro_lead_conversion_report','pro_role_route_capability') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';

-- ===== jobsite-links-autofill-local.sql =====
-- LOCAL PRO ONLY. Round 10 (2026-11-15), Jobsite (Houzz Pro parity rows 13, 20, 78, 79).
--  * Schedule dependencies (row 13): each existing predecessor link of the job plan can be
--    finish-to-start (FS, default) or start-to-start (SS) with a lag in days (side table keyed by the
--    task pair; the plan writer keeps owning WHICH predecessors exist). Existing links are migrated
--    once as FS + 0 days (nothing is rewritten). A date change can be previewed with every dependent
--    task that must move to respect FS/SS + lag (push forward, durations kept) and applied in one
--    transaction (schedule revision CAS, 40001 → 409), then undone once while nothing changed since.
--    Multi-job read of planned tasks for a combined schedule.
--  * Daily log automation (row 20): suggestions for one job and date: crew and minutes from the hours
--    ledger (pro_time_report_rows) and timers of that day, tasks completed that day (task history) and
--    tasks planned for that day. Weather comes from the mock adapter in the app (never a provider).
--    Reminder: in-app notification «daily_log_missing» (Round 9 center) for yesterday's work without
--    a daily log entry (owner only; derived on read like the other events, idempotent).
--  * Task templates (row 78): apply with assignee mapping in one transaction (existing apply writer +
--    existing task writer for each mapped task), with its own receipt.
-- Patterns: RLS on, service_role only, security invoker, CAS 40001, idempotent actionId receipts,
-- immutable history. Nothing is sent; no third party is called.
begin;
create table if not exists public.pro_schedule_link_rules(
 owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,task_id uuid not null,predecessor_id uuid not null,
 kind text not null default 'fs' check(kind in('fs','ss')),lag_days integer not null default 0 check(lag_days between -60 and 365),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,work_id,task_id,predecessor_id),check(task_id<>predecessor_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,work_id,predecessor_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade);
create table if not exists public.pro_schedule_round10_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,work_id text not null,
 kind text not null check(kind in('link','shift','undo')),input jsonb not null,result jsonb not null,before_state jsonb,after_state jsonb,
 revision_after integer,undo_of uuid,at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade);
create unique index if not exists pro_schedule_round10_undo_once on public.pro_schedule_round10_actions(owner_id,undo_of) where undo_of is not null;
create index if not exists pro_schedule_round10_last on public.pro_schedule_round10_actions(owner_id,work_id,at desc);
create table if not exists public.pro_task_template_map_actions(
 owner_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,
 at timestamptz not null default clock_timestamp(),primary key(owner_id,action_id));
do $$declare t text;begin
 foreach t in array array['pro_schedule_round10_actions','pro_task_template_map_actions'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_immutable',t);
  execute format('create trigger %I before update or delete on public.%I for each row when (pg_trigger_depth()=0) execute function public.pro_round10_immutable()',t||'_immutable',t);
 end loop;
 foreach t in array array['pro_schedule_link_rules','pro_schedule_round10_actions','pro_task_template_map_actions'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;
-- One-time migration: every existing predecessor link becomes an explicit FS + 0 rule (same meaning as before).
insert into public.pro_schedule_link_rules(owner_id,work_id,task_id,predecessor_id) select owner_id,work_id,task_id,predecessor_id from public.pro_work_schedule_dependencies on conflict do nothing;

-- Current links of a job (only pairs that still exist in the plan; rule defaults FS + 0).
create or replace function public.pro_schedule_links_of(p_owner uuid,p_work text) returns table(task_id uuid,predecessor_id uuid,kind text,lag_days integer,revision integer) language sql stable security invoker set search_path=public,pg_temp as $$
 select d.task_id,d.predecessor_id,coalesce(r.kind,'fs'),coalesce(r.lag_days,0),coalesce(r.revision,0) from public.pro_work_schedule_dependencies d
 join public.pro_work_tasks a on a.owner_id=d.owner_id and a.id=d.task_id and not a.archived join public.pro_work_tasks b on b.owner_id=d.owner_id and b.id=d.predecessor_id and not b.archived
 left join public.pro_schedule_link_rules r on r.owner_id=d.owner_id and r.work_id=d.work_id and r.task_id=d.task_id and r.predecessor_id=d.predecessor_id
 where d.owner_id=p_owner and d.work_id=p_work $$;

create or replace function public.pro_schedule_links_read(p_owner uuid,p_work text) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare last_shift public.pro_schedule_round10_actions;rev integer;
begin
 perform public.pro_work_schedule_owner(p_owner,p_work);
 select revision into rev from public.pro_work_schedule_heads where owner_id=p_owner and work_id=p_work;
 select * into last_shift from public.pro_schedule_round10_actions where owner_id=p_owner and work_id=p_work and kind='shift' order by at desc limit 1;
 return jsonb_build_object('workId',p_work,'revision',coalesce(rev,0),
  'tasks',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'status',t.status,'assignee',t.assignee,'start',to_char(p.planned_start,'YYYY-MM-DD'),'end',to_char(p.planned_end,'YYYY-MM-DD'),'phaseId',p.phase_id) order by p.planned_start nulls last,t.title,t.id)
   from public.pro_work_tasks t join public.pro_work_schedule_plans p on p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id where t.owner_id=p_owner and t.work_id=p_work and not t.archived),'[]'::jsonb),
  'links',coalesce((select jsonb_agg(jsonb_build_object('taskId',l.task_id,'predecessorId',l.predecessor_id,'kind',l.kind,'lagDays',l.lag_days,'revision',l.revision) order by l.task_id,l.predecessor_id) from public.pro_schedule_links_of(p_owner,p_work) l),'[]'::jsonb),
  'lastShift',case when last_shift.action_id is null then null else jsonb_build_object('actionId',last_shift.action_id,'at',last_shift.at,'moved',jsonb_array_length(coalesce(last_shift.after_state,'[]'::jsonb)),
   'undone',exists(select 1 from public.pro_schedule_round10_actions u where u.owner_id=p_owner and u.undo_of=last_shift.action_id),'undoable',last_shift.revision_after=coalesce(rev,0) and not exists(select 1 from public.pro_schedule_round10_actions u where u.owner_id=p_owner and u.undo_of=last_shift.action_id)) end);
end $$;

-- Dates every task must take when one task gets [p_start,p_end]: dependents are pushed forward (never
-- pulled back) until every FS/SS + lag rule holds; durations are kept. Returns the moved tasks only.
create or replace function public.pro_schedule_shift_compute(p_owner uuid,p_work text,p_task uuid,p_start date,p_end date) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare plan jsonb:='{}'::jsonb;orig jsonb;l record;changed boolean:=true;guard integer:=0;need date;s date;e date;ps date;pe date;answer jsonb:='[]'::jsonb;k text;
begin
 if p_start is null or p_end is null or p_end<p_start or p_start<date'1900-01-01' or p_end>date'2100-12-31' then raise exception 'Invalid period' using errcode='22023';end if;
 select coalesce(jsonb_object_agg(p.task_id::text,jsonb_build_object('s',p.planned_start,'e',p.planned_end)),'{}'::jsonb) into plan from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.id=p.task_id and not t.archived
  where p.owner_id=p_owner and p.work_id=p_work and p.planned_start is not null;
 if not plan ? p_task::text then raise exception 'Task has no planned period' using errcode='22023';end if;
 orig:=plan;plan:=jsonb_set(plan,array[p_task::text],jsonb_build_object('s',p_start,'e',p_end));
 while changed loop
  changed:=false;guard:=guard+1;if guard>600 then raise exception 'Schedule rules do not settle' using errcode='22023';end if;
  for l in select * from public.pro_schedule_links_of(p_owner,p_work) loop
   if not(plan ? l.task_id::text and plan ? l.predecessor_id::text) then continue;end if;
   ps:=(plan->l.predecessor_id::text->>'s')::date;pe:=(plan->l.predecessor_id::text->>'e')::date;s:=(plan->l.task_id::text->>'s')::date;e:=(plan->l.task_id::text->>'e')::date;
   need:=case when l.kind='fs' then pe+1+l.lag_days else ps+l.lag_days end;
   if s<need and l.task_id<>p_task then
    if e+(need-s)>date'2100-12-31' then raise exception 'Shift beyond supported dates' using errcode='22023';end if;
    plan:=jsonb_set(plan,array[l.task_id::text],jsonb_build_object('s',need,'e',e+(need-s)));changed:=true;end if;
  end loop;
 end loop;
 for k in select key from jsonb_each(plan) loop
  if plan->k<>orig->k then answer:=answer||jsonb_build_array(jsonb_build_object('taskId',k,'title',(select title from public.pro_work_tasks where owner_id=p_owner and id=k::uuid),
   'fromStart',orig->k->>'s','fromEnd',orig->k->>'e','toStart',plan->k->>'s','toEnd',plan->k->>'e','moved',k=p_task::text));end if;
 end loop;
 return answer;
end $$;
create or replace function public.pro_schedule_shift_preview(p_owner uuid,p_work text,p_task uuid,p_start date,p_end date) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin perform public.pro_work_schedule_owner(p_owner,p_work);
 return jsonb_build_object('revision',coalesce((select revision from public.pro_work_schedule_heads where owner_id=p_owner and work_id=p_work),0),'changes',public.pro_schedule_shift_compute(p_owner,p_work,p_task,p_start,p_end));end $$;

create or replace function public.pro_schedule_mutate(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;wid text;rev integer;cur integer;receipt public.pro_schedule_round10_actions;answer jsonb;changes jsonb;c jsonb;tid uuid;pid uuid;rule public.pro_schedule_link_rules;
 orig public.pro_schedule_round10_actions;before_json jsonb;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid schedule action' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(x order by x) into keys from jsonb_object_keys(p_input) x;
 if keys is distinct from (case act when 'link_set' then array['action','actionId','kind','lagDays','predecessorId','revision','taskId','workId'] when 'shift' then array['action','actionId','end','revision','start','taskId','workId'] when 'undo' then array['action','actionId','revision','shiftId','workId'] end)
  or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce(p_input->>'revision'~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric>2147483646 then raise exception 'Unexpected schedule fields' using errcode='22023';end if;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 wid:=p_input->>'workId';rev:=(p_input->>'revision')::integer;perform public.pro_work_schedule_owner(p_owner,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-schedule-round10:'||p_owner::text||':'||aid::text,0));
 select * into receipt from public.pro_schedule_round10_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 -- Same per-job serialization as the plan writer.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_owner::text||':'||wid,0));
 if act='link_set' then
  begin tid:=(p_input->>'taskId')::uuid;pid:=(p_input->>'predecessorId')::uuid;exception when others then raise exception 'Invalid link' using errcode='22023';end;
  if p_input->>'kind' not in('fs','ss') or jsonb_typeof(p_input->'lagDays') is distinct from 'number' or(p_input->>'lagDays')!~'^-?[0-9]{1,3}$' or(p_input->>'lagDays')::integer not between -60 and 365 then raise exception 'Invalid link rule' using errcode='22023';end if;
  if not exists(select 1 from public.pro_schedule_links_of(p_owner,wid) l where l.task_id=tid and l.predecessor_id=pid) then raise exception 'Link unavailable' using errcode='P0002';end if;
  select * into rule from public.pro_schedule_link_rules where owner_id=p_owner and work_id=wid and task_id=tid and predecessor_id=pid for update;
  if coalesce(rule.revision,0)<>rev then raise exception 'Link changed' using errcode='40001';end if;
  before_json:=case when rule.task_id is null then jsonb_build_object('kind','fs','lagDays',0) else jsonb_build_object('kind',rule.kind,'lagDays',rule.lag_days) end;
  insert into public.pro_schedule_link_rules(owner_id,work_id,task_id,predecessor_id,kind,lag_days) values(p_owner,wid,tid,pid,p_input->>'kind',(p_input->>'lagDays')::integer)
   on conflict(owner_id,work_id,task_id,predecessor_id) do update set kind=excluded.kind,lag_days=excluded.lag_days,revision=public.pro_schedule_link_rules.revision+1,updated_at=clock_timestamp() returning * into rule;
  answer:=jsonb_build_object('action','link_set','taskId',tid,'predecessorId',pid,'kind',rule.kind,'lagDays',rule.lag_days,'revision',rule.revision);
  insert into public.pro_schedule_round10_actions(owner_id,action_id,work_id,kind,input,result,before_state,after_state) values(p_owner,aid,wid,'link',p_input,answer,before_json,jsonb_build_object('kind',rule.kind,'lagDays',rule.lag_days));
  return answer;
 end if;
 select coalesce(revision,0) into cur from public.pro_work_schedule_heads where owner_id=p_owner and work_id=wid;cur:=coalesce(cur,0);
 if cur<>rev then raise exception 'Schedule changed' using errcode='40001';end if;
 if act='shift' then
  begin tid:=(p_input->>'taskId')::uuid;exception when others then raise exception 'Invalid task' using errcode='22023';end;
  if coalesce(p_input->>'start','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_input->>'end','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid dates' using errcode='22023';end if;
  changes:=public.pro_schedule_shift_compute(p_owner,wid,tid,(p_input->>'start')::date,(p_input->>'end')::date);
  if jsonb_array_length(changes)=0 then raise exception 'Nothing to change' using errcode='22023';end if;
 else
  begin select * into orig from public.pro_schedule_round10_actions where owner_id=p_owner and action_id=(p_input->>'shiftId')::uuid and work_id=wid and kind='shift';exception when others then raise exception 'Invalid shift' using errcode='22023';end;
  if orig.action_id is null then raise exception 'Shift unavailable' using errcode='P0002';end if;
  if orig.revision_after<>cur or exists(select 1 from public.pro_schedule_round10_actions where owner_id=p_owner and undo_of=orig.action_id) then raise exception 'Schedule changed since that shift' using errcode='40001';end if;
  select coalesce(jsonb_agg(jsonb_build_object('taskId',x->>'taskId','title',x->>'title','fromStart',x->>'toStart','fromEnd',x->>'toEnd','toStart',x->>'fromStart','toEnd',x->>'fromEnd')),'[]'::jsonb) into changes from jsonb_array_elements(orig.after_state) x;
 end if;
 for c in select value from jsonb_array_elements(changes) loop
  update public.pro_work_schedule_plans set planned_start=(c->>'toStart')::date,planned_end=(c->>'toEnd')::date where owner_id=p_owner and work_id=wid and task_id=(c->>'taskId')::uuid
   and planned_start=(c->>'fromStart')::date and planned_end=(c->>'fromEnd')::date;
  if not found then raise exception 'Plan changed' using errcode='40001';end if;
 end loop;
 insert into public.pro_work_schedule_heads(owner_id,work_id,revision) values(p_owner,wid,cur+1) on conflict(owner_id,work_id) do update set revision=excluded.revision,updated_at=now();
 answer:=jsonb_build_object('action',act,'workId',wid,'revision',cur+1,'changes',changes);
 insert into public.pro_schedule_round10_actions(owner_id,action_id,work_id,kind,input,result,before_state,after_state,revision_after,undo_of)
  values(p_owner,aid,wid,act,p_input,answer,(select jsonb_agg(jsonb_build_object('taskId',x->>'taskId','start',x->>'fromStart','end',x->>'fromEnd')) from jsonb_array_elements(changes) x),changes,cur+1,case when act='undo' then orig.action_id end);
 return answer;
end $$;

-- Combined schedule: planned tasks of every active job overlapping a period (≤ 500 rows).
create or replace function public.pro_schedule_multi_read(p_owner uuid,p_from date,p_to date) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_owner),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_from is null or p_to is null or p_from>p_to or p_to-p_from>366 then raise exception 'Invalid period' using errcode='22023';end if;
 return jsonb_build_object('from',to_char(p_from,'YYYY-MM-DD'),'to',to_char(p_to,'YYYY-MM-DD'),
  'items',coalesce((select jsonb_agg(x.j order by x.s,x.svc,x.title) from(select jsonb_build_object('workId',w.id,'service',w.service,'client',coalesce(w.client,''),'taskId',t.id,'title',t.title,'status',t.status,'assignee',t.assignee,
     'start',to_char(p.planned_start,'YYYY-MM-DD'),'end',to_char(p.planned_end,'YYYY-MM-DD'),'overdue',t.status='open' and p.planned_end<(now() at time zone 'America/Costa_Rica')::date) j,p.planned_start s,w.service svc,t.title
    from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.id=p.task_id and not t.archived join public.pro_work w on w.user_id=p.owner_id and w.id=p.work_id and not coalesce(w.cancelled,false)
    where p.owner_id=p_owner and p.planned_start<=p_to and p.planned_end>=p_from order by p.planned_start,w.service,t.title limit 500)x),'[]'::jsonb));
end $$;

-- Daily log suggestions for one job and Costa Rica date (read only; the entry is saved by the existing writer).
create or replace function public.pro_daily_log_autofill(p_owner uuid,p_work text,p_date date) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 perform public.pro_work_schedule_owner(p_owner,p_work);
 if p_date is null or p_date<date'1900-01-01' or p_date>date'2100-12-31' then raise exception 'Invalid date' using errcode='22023';end if;
 return jsonb_build_object('workId',p_work,'date',to_char(p_date,'YYYY-MM-DD'),
  'crew',(select jsonb_build_object('people',coalesce(jsonb_agg(jsonb_build_object('key',k,'name',n,'minutes',m) order by n),'[]'::jsonb),'count',count(*),'minutes',coalesce(sum(m),0)::integer)
   from(select k,min(n) n,sum(m)::integer m from(
     select r.person_key k,coalesce(nullif(r.person_name,''),'—') n,r.minutes m from public.pro_time_report_rows(p_owner,p_date,p_date) r where r.work_id=p_work
     union all select 'person:'||t.person_id::text,coalesce(nullif(t.person_name,''),'—'),0 from public.pro_work_timers t where t.owner_id=p_owner and t.work_id=p_work and t.status in('running','stopped') and(t.started_at at time zone 'America/Costa_Rica')::date=p_date) y group by k) z),
  'completed',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title) order by t.title) from public.pro_work_tasks t where t.owner_id=p_owner and t.work_id=p_work and not t.archived and t.status='done'
   and exists(select 1 from public.pro_work_task_history h where h.owner_id=t.owner_id and h.task_id=t.id and h.action='complete' and(h.at at time zone 'America/Costa_Rica')::date=p_date)),'[]'::jsonb),
  'planned',coalesce((select jsonb_agg(jsonb_build_object('id',t.id,'title',t.title) order by t.title) from public.pro_work_tasks t join public.pro_work_schedule_plans p on p.owner_id=t.owner_id and p.task_id=t.id
   where t.owner_id=p_owner and t.work_id=p_work and not t.archived and t.status='open' and p_date between p.planned_start and p.planned_end),'[]'::jsonb),
  'existing',exists(select 1 from public.pro_daily_logs l where l.owner_id=p_owner and l.work_id=p_work and l.log_date=p_date and not l.archived));
end $$;

-- Task template application with assignee mapping (one transaction, own receipt).
create or replace function public.pro_task_template_apply_mapped(p_owner uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;receipt public.pro_task_template_map_actions;inner_input jsonb;inner_result jsonb;map jsonb;k text;tid uuid;t public.pro_work_tasks;mapped integer:=0;answer jsonb;target text;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or p_input->>'action' is distinct from 'apply' or jsonb_typeof(p_input->'assigneeMap') is distinct from 'object' then raise exception 'Invalid mapped application' using errcode='22023';end if;
 map:=p_input->'assigneeMap';if(select count(*) from jsonb_object_keys(map))>20 then raise exception 'Too many assignees' using errcode='22023';end if;
 for k in select key from jsonb_each(map) loop
  if length(k) not between 1 and 160 or jsonb_typeof(map->k) is distinct from 'string' or length(btrim(map->>k))>160 then raise exception 'Invalid assignee mapping' using errcode='22023';end if;end loop;
 begin aid:=(p_input->>'actionId')::uuid;exception when others then raise exception 'Invalid action id' using errcode='22023';end;
 perform pg_advisory_xact_lock(hashtextextended('pro-task-template-map:'||p_owner::text||':'||aid::text,0));
 select * into receipt from public.pro_task_template_map_actions where owner_id=p_owner and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Action id reused' using errcode='22023';end if;return receipt.result||jsonb_build_object('replayed',true);end if;
 inner_input:=p_input-'assigneeMap';inner_result:=public.pro_task_templates_mutate(p_owner,inner_input);
 for tid in select value::uuid from jsonb_array_elements_text(p_input->'newTaskIds') loop
  select * into t from public.pro_work_tasks where owner_id=p_owner and id=tid;
  if t.id is null then continue;end if;
  if btrim(t.assignee)<>'' and map ? btrim(t.assignee) then
   target:=btrim(map->>btrim(t.assignee));
   if target is distinct from btrim(t.assignee) then
    perform public.pro_work_tasks_mutate(p_owner,jsonb_build_object('action','update','actionId',public.pro_lead_import_uuid('pro-task-template-map:'||aid::text||':'||tid::text),'workId',t.work_id,'taskId',t.id,'revision',t.revision,
     'title',t.title,'details',t.details,'assignee',target,'dueDate',case when t.due_date is null then null else to_char(t.due_date,'YYYY-MM-DD') end));mapped:=mapped+1;end if;
  end if;
 end loop;
 answer:=jsonb_build_object('action','apply_mapped','applied',inner_result,'mapped',mapped);
 insert into public.pro_task_template_map_actions(owner_id,action_id,input,result) values(p_owner,aid,p_input,answer);
 return answer;
end $$;

-- Notifications: new event «daily_log_missing» (Round 9 center).
alter table public.pro_notifications drop constraint if exists pro_notifications_event_check;
alter table public.pro_notifications add constraint pro_notifications_event_check check(event in('task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received','daily_log_missing'));
create or replace function public.pro_notification_events() returns text[] language sql immutable security invoker set search_path=public,pg_temp as $$
 select array['task_assigned','task_due','client_message','quote_accepted','quote_changes','invoice_paid','invoice_overdue','bid_received','daily_log_missing']
$$;
-- Same derivation as pro-notifications-local.sql plus the Round 10 daily log reminder.
create or replace function public.pro_notifications_sync(p_owner uuid,p_person uuid,p_today date) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare st jsonb;who text;n integer;plan record;item jsonb;overdue jsonb:='[]'::jsonb;
begin
 if not public.pro_notification_person_ok(p_owner,p_person) then raise exception 'Forbidden' using errcode='42501';end if;
 st:=public.pro_notification_settings_json(p_owner,p_person);who:=public.pro_notification_person_name(p_owner,p_person);
 -- Overdue payment-plan installments (after the person's grace days), from the plan's own state.
 for plan in select id,work_id from public.pro_payment_plans where owner_id=p_owner and status='active' limit 200 loop
  for item in select value from jsonb_array_elements(coalesce(public.pro_payment_plan_state(p_owner,plan.id,p_today-(st->>'overdueGraceDays')::integer)->'items','[]'::jsonb)) loop
   if item->>'status'='overdue' then overdue:=overdue||jsonb_build_array(jsonb_build_object('key',plan.id::text||':'||coalesce(item->>'seq','')||':'||coalesce(item->>'dueDate',''),
    'title',left(coalesce((select service from public.pro_work where user_id=p_owner and id=plan.work_id),'Plan de pagos'),200),'body',coalesce(item->>'dueDate',''),
    'link',jsonb_build_object('tab','pro_agenda','cita',plan.work_id,'vistaTrabajo','costs','due',item->>'dueDate','amountCents',coalesce((item->>'amountCents')::bigint,0)-coalesce((item->>'appliedCents')::bigint,0))));end if;
  end loop;
 end loop;
 -- One statement, no temporary tables; only enabled in-app events become notifications; email drafts
 -- only where the person chose email (never sent).
 with events(event,source_key,title,body,link,at) as(
  -- Tasks assigned to this person (by its name as «Responsable»).
  select 'task_assigned',t.id::text||':'||lower(t.assignee),left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks'),t.updated_at
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where who is not null and t.owner_id=p_owner and not t.archived and t.status='open' and lower(btrim(t.assignee))=lower(who) and t.updated_at>clock_timestamp()-interval '60 days'
  union all
  -- Due soon / overdue tasks of this person (unassigned tasks: the owner).
  select 'task_due',t.id::text||':'||t.due_date::text,left(t.title,200),left(w.service,400),jsonb_build_object('tab','pro_agenda','cita',t.work_id,'vistaTrabajo','tasks','due',t.due_date::text,'overdue',t.due_date<p_today),clock_timestamp()
   from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
   where t.owner_id=p_owner and not t.archived and t.status='open' and t.due_date is not null and t.due_date<=p_today+(st->>'dueSoonDays')::integer and t.due_date>=p_today-30
    and (who is not null and lower(btrim(t.assignee))=lower(who) or btrim(t.assignee)='' and p_person=p_owner)
  union all
  -- Customer messages in job threads (last 30 days).
  select 'client_message',m.id::text,left(coalesce(nullif(m.author_name,''),'Cliente'),200),left(m.body,400),jsonb_build_object('tab','pro_agenda','cita',m.work_id,'vistaTrabajo','messages'),m.created_at
   from public.pro_work_messages m where m.owner_id=p_owner and m.side='client' and m.created_at>clock_timestamp()-interval '30 days'
  union all
  -- Customer answers to shared quotes.
  select case s.status when 'accepted' then 'quote_accepted' else 'quote_changes' end,p.id::text||':'||s.status||':'||s.revision,left(e.title,200),'',jsonb_build_object('tab','quotes','estimacionPrivada',p.estimate_id::text),p.created_at
   from public.pro_private_estimate_publications p join public.pro_private_estimate_publication_states s on s.publication_id=p.id join public.pro_private_estimates e on e.owner_id=p.owner_id and e.id=p.estimate_id
   where p.owner_id=p_owner and s.status in('accepted','changes_requested') and p.created_at>clock_timestamp()-interval '90 days'
  union all
  -- Payments applied to invoice drafts (not voided).
  select 'invoice_paid',a.id::text,left(d.title,200),a.amount_cents::text,jsonb_build_object('tab','pro_billing','amountCents',a.amount_cents),a.created_at
   from public.pro_invoice_payment_applications a join public.pro_invoice_drafts d on d.user_id=a.user_id and d.id=a.draft_id
   where a.user_id=p_owner and a.created_at>clock_timestamp()-interval '30 days' and not exists(select 1 from public.pro_invoice_payment_voids v where v.user_id=a.user_id and v.application_id=a.id)
  union all
  select 'invoice_overdue',o->>'key',o->>'title',o->>'body',o->'link',clock_timestamp() from jsonb_array_elements(overdue) o
  union all
  -- Vendor bid responses.
  select 'bid_received',r.package_id::text||':'||r.supplier_id::text,left(b.title,200),left(coalesce((select v.name from public.pro_expense_suppliers v where v.user_id=r.owner_id and v.id=r.supplier_id),''),400),jsonb_build_object('tab','pro_agenda','cita',b.work_id,'vistaTrabajo','bids'),r.recorded_at
   from public.pro_bid_responses r join public.pro_bid_packages b on b.owner_id=r.owner_id and b.id=r.package_id
   where r.owner_id=p_owner and r.recorded_at>clock_timestamp()-interval '30 days'
  union all
  -- Round 10: daily log reminder (owner only). Yesterday (Costa Rica) had work on the job (hours,
  -- a timer or a completed task) but the job has no daily log entry for that date.
  select 'daily_log_missing',w.id||':'||(p_today-1)::text,left(w.service,200),left(coalesce(w.client,''),400),jsonb_build_object('tab','pro_agenda','cita',w.id,'vistaTrabajo','updates','date',(p_today-1)::text),clock_timestamp()
   from public.pro_work w where p_person=p_owner and w.user_id=p_owner and not coalesce(w.cancelled,false)
    and not exists(select 1 from public.pro_daily_logs l where l.owner_id=p_owner and l.work_id=w.id and l.log_date=p_today-1 and not l.archived)
    and(exists(select 1 from public.pro_time_entries e where e.owner_id=p_owner and e.work_id=w.id and e.status='stopped' and e.recorded_on=p_today-1)
     or exists(select 1 from public.pro_work_timers t where t.owner_id=p_owner and t.work_id=w.id and(t.started_at at time zone 'America/Costa_Rica')::date=p_today-1)
     or exists(select 1 from public.pro_work_task_history h where h.owner_id=p_owner and h.work_id=w.id and h.action='complete' and(h.at at time zone 'America/Costa_Rica')::date=p_today-1))),
 ins as(insert into public.pro_notifications(owner_id,person_id,event,source_key,title,body,link,created_at)
  select distinct on(e.event,e.source_key) p_owner,p_person,e.event,e.source_key,e.title,e.body,e.link,least(coalesce(e.at,clock_timestamp()),clock_timestamp())
  from events e where public.pro_notification_enabled(st,e.event,'inApp')
  on conflict(owner_id,person_id,event,source_key) do nothing returning *),
 drafts as(insert into public.pro_notification_email_drafts(owner_id,person_id,notification_id,subject,body)
  select i.owner_id,i.person_id,i.id,left('ContrataCR Pro: '||i.title,200),i.title||case when i.body<>'' then E'\n'||i.body else '' end
  from ins i where public.pro_notification_enabled(st,i.event,'email') returning 1)
 select count(*) into n from ins;
 return n;
end $$;
do $$declare f record;begin
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in(
  'pro_schedule_links_of','pro_schedule_links_read','pro_schedule_shift_compute','pro_schedule_shift_preview','pro_schedule_mutate','pro_schedule_multi_read','pro_daily_log_autofill','pro_task_template_apply_mapped','pro_notification_events','pro_notifications_sync') loop
  execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;
end $$;
commit;
notify pgrst,'reload schema';
